module Problem4_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic X
);
    // Combinational DUT with no clock/reset; sample assertions on posedge A.

    // X equals the RTL sum-of-products function.
    check_function_equivalence: assert property (
        @(posedge A)
        X == ((~A & ~B & ~C & D & ~E) |
              (~A & ~B & ~C & D & E) |
              (~A & ~B & C & ~D & E) |
              (~A & ~B & C & D & E) |
              (~A & B & ~C & ~D & E) |
              (~A & B & ~C & D & E) |
              (~A & B & C & ~D & E) |
              (A & ~B & ~C & ~D & E) |
              (A & ~B & ~C & D & E) |
              (A & ~B & C & D & E) |
              (A & B & C & ~D & E) |
              (A & B & C & D & E))
    );

    // When E=0, X equals (~A & ~B & ~C & D).
    check_E0_equivalence: assert property (
        @(posedge A) (E == 1'b0) |-> (X == (~A & ~B & ~C & D))
    );

    // With E=1 and A=0,B=0,C=1, X is 1 regardless of D.
    check_E1_A0B0C1_true: assert property (
        @(posedge A) (E && ~A && ~B && C) |-> (X == 1'b1)
    );

    // With E=1 and A=0,B=1,C=0, X is 1 regardless of D.
    check_E1_A0B1C0_true: assert property (
        @(posedge A) (E && ~A && B && ~C) |-> (X == 1'b1)
    );

    // With E=1 and A=1,B=0,C=0, X is 1 regardless of D.
    check_E1_A1B0C0_true: assert property (
        @(posedge A) (E && A && ~B && ~C) |-> (X == 1'b1)
    );

    // With E=1 and A=1,B=1,C=1, X is 1 regardless of D.
    check_E1_A1B1C1_true: assert property (
        @(posedge A) (E && A && B && C) |-> (X == 1'b1)
    );

    // With E=1 and A=1,B=1,C=0, X is always 0.
    check_E1_A1B1C0_false: assert property (
        @(posedge A) (E && A && B && ~C) |-> (X == 1'b0)
    );

    // With E=1 and A=1,B=0,C=1,D=1, X must be 1.
    check_E1_A1B0C1_D1_true: assert property (
        @(posedge A) (E && A && ~B && C && D) |-> (X == 1'b1)
    );

    // With E=1 and A=1,B=0,C=1,D=0, X must be 0.
    check_E1_A1B0C1_D0_false: assert property (
        @(posedge A) (E && A && ~B && C && ~D) |-> (X == 1'b0)
    );

    // With E=1 and A=0,B=0,C=0,D=1, X must be 1.
    check_E1_A0B0C0_D1_true: assert property (
        @(posedge A) (E && ~A && ~B && ~C && D) |-> (X == 1'b1)
    );

    // With E=1 and A=0,B=0,C=0,D=0, X must be 0.
    check_E1_A0B0C0_D0_false: assert property (
        @(posedge A) (E && ~A && ~B && ~C && ~D) |-> (X == 1'b0)
    );
endmodule

module adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] Z
);
    ///// Functional behavior /////
    // Z equals the 4-bit sum modulo 10.
    check_mod10_behavior: assert property (
        @(posedge CLK) Z == ((A + B) % 4'd10)
    );

    // When 4-bit sum <= 9, Z equals the sum.
    check_pass_through_when_sum_le_9: assert property (
        @(posedge CLK) ((A + B) <= 4'd9) |-> (Z == (A + B))
    );

    // When 4-bit sum >= 10, Z equals sum - 10.
    check_subtract10_when_sum_ge10: assert property (
        @(posedge CLK) ((A + B) >= 4'd10) |-> (Z == ((A + B) - 4'd10))
    );

    // Z is always a decimal digit in the range 0..9.
    check_output_in_range_0_to_9: assert property (
        @(posedge CLK) (Z <= 4'd9)
    );

    // For 4-bit sums 10..15, Z must be in 0..5.
    check_remainder_bound_high_sums: assert property (
        @(posedge CLK) ((A + B) >= 4'd10) |-> (Z <= 4'd5)
    );

    // If inputs are unchanged cycle-to-cycle, output is unchanged.
    check_stability_when_inputs_stable: assert property (
        @(posedge CLK) (A == $past(A) && B == $past(B)) |-> (Z == $past(Z))
    );

    // If the 4-bit sum is unchanged, Z is unchanged.
    check_stability_when_sum_stable: assert property (
        @(posedge CLK) ((A + B) == $past(A + B)) |-> (Z == $past(Z))
    );

    // Corner case: 4-bit sum == 10 -> Z == 0.
    check_case_sum_eq_10: assert property (
        @(posedge CLK) ((A + B) == 4'd10) |-> (Z == 4'd0)
    );

    // Corner case: 4-bit sum == 15 -> Z == 5.
    check_case_sum_eq_15: assert property (
        @(posedge CLK) ((A + B) == 4'd15) |-> (Z == 4'd5)
    );

    // Corner case: 4-bit sum == 0 -> Z == 0.
    check_case_sum_eq_0: assert property (
        @(posedge CLK) ((A + B) == 4'd0) |-> (Z == 4'd0)
    );
endmodule

verilog_code:
module mix_columns
(
	output [31:0] mix_out_enc,
	output [31:0] mix_out_dec,
	input  [31:0] mix_in
);

localparam integer SIZE      = 32;
localparam integer WORD_SIZE = 8;
localparam integer NUM_WORDS = 4;

wire [WORD_SIZE - 1 : 0] col  [0 : NUM_WORDS - 1];
wire [WORD_SIZE - 1 : 0] sum_p[0 : NUM_WORDS - 1];
wire [WORD_SIZE - 1 : 0] y    [0 : NUM_WORDS - 2];

function [7:0] aes_mult_02;
  input [7:0] data_in;
  begin
    aes_mult_02 = (data_in << 1) ^ {8{data_in[7]}} & 8'h1b;
  end
endfunction

function [7:0] aes_mult_04;
  input [7:0] data_in;
  begin
    aes_mult_04 = ((data_in << 2) ^ {8{data_in[6]}} & 8'h1b) ^ {8{data_in[7]}} & 8'h36;
  end
endfunction

generate
	genvar i;
	for(i = 0 ; i < NUM_WORDS; i = i + 1)
	begin:WBT
		assign col[i] = mix_in[WORD_SIZE*(i + 1) - 1: WORD_SIZE*i];
	end
endgenerate

generate
	genvar j;
	for(j = 0; j < NUM_WORDS; j = j + 1)
		begin:DMCO
			assign sum_p[j] = col[(j + 1)%NUM_WORDS] ^ col[(j + 2)%NUM_WORDS] ^ col[(j + 3)%NUM_WORDS];
			assign mix_out_enc[ WORD_SIZE*(j + 1) - 1 : WORD_SIZE*j] = aes_mult_02(col[j] ^ col[(j + NUM_WORDS - 1)%NUM_WORDS]) ^ sum_p[j];
		end
endgenerate

assign y[0] = aes_mult_04(col[2] ^ col[0]); 
assign y[1] = aes_mult_04(col[3] ^ col[1]);
assign y[2] = aes_mult_02(  y[1] ^   y[0]);  
assign mix_out_dec = mix_out_enc ^ {2{y[2] ^ y[1], y[2] ^ y[0]}};

endmodule

sva_code:
module mix_columns_sva (
    input  logic         CLK,
    input  logic         RESETn,
    input  logic [31:0]  mix_out_enc,
    input  logic [31:0]  mix_out_dec,
    input  logic [31:0]  mix_in
);
    // Combinational DUT with no clock/reset; use CLK/RESETn only for sampling in SVA.

    // Local re-implementation of DUT helper functions
    function automatic logic [7:0] aes_mult_02 (input logic [7:0] data_in);
        aes_mult_02 = (data_in << 1) ^ (({8{data_in[7]}}) & 8'h1b);
    endfunction

    function automatic logic [7:0] aes_mult_04 (input logic [7:0] data_in);
        aes_mult_04 = ((data_in << 2) ^ (({8{data_in[6]}}) & 8'h1b)) ^ (({8{data_in[7]}}) & 8'h36);
    endfunction

    // Byte slices
    logic [7:0] col0, col1, col2, col3;
    assign col0 = mix_in[7:0];
    assign col1 = mix_in[15:8];
    assign col2 = mix_in[23:16];
    assign col3 = mix_in[31:24];

    // Sums used in enc computation
    logic [7:0] sum_p0, sum_p1, sum_p2, sum_p3;
    assign sum_p0 = col1 ^ col2 ^ col3;
    assign sum_p1 = col2 ^ col3 ^ col0;
    assign sum_p2 = col3 ^ col0 ^ col1;
    assign sum_p3 = col0 ^ col1 ^ col2;

    // Expected encryption bytes and 32b value
    logic [7:0] enc0_e, enc1_e, enc2_e, enc3_e;
    assign enc0_e = aes_mult_02(col0 ^ col3) ^ sum_p0;
    assign enc1_e = aes_mult_02(col1 ^ col0) ^ sum_p1;
    assign enc2_e = aes_mult_02(col2 ^ col1) ^ sum_p2;
    assign enc3_e = aes_mult_02(col3 ^ col2) ^ sum_p3;

    logic [31:0] enc_expected;
    assign enc_expected = {enc3_e, enc2_e, enc1_e, enc0_e};

    // Expected decryption XOR pattern from inputs
    logic [7:0] y0, y1, y2;
    assign y0 = aes_mult_04(col2 ^ col0);
    assign y1 = aes_mult_04(col3 ^ col1);
    assign y2 = aes_mult_02(y1 ^ y0);

    logic [15:0] patt16;
    logic [31:0] patt32;
    assign patt16 = { (y2 ^ y1), (y2 ^ y0) };
    assign patt32 = {patt16, patt16};

    // Expected decryption output
    logic [31:0] dec_expected;
    assign dec_expected = enc_expected ^ patt32;

    // Diff between dec and enc (should equal patt32)
    logic [31:0] diff;
    assign diff = mix_out_dec ^ mix_out_enc;

    ///// Functional checks /////
    // mix_out_enc equals the defined AES MixColumns encoding of mix_in.
    check_enc_full: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_enc == enc_expected
    );

    // Byte 0 of mix_out_enc matches formula.
    check_enc_byte0: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_enc[7:0] == enc0_e
    );

    // Byte 1 of mix_out_enc matches formula.
    check_enc_byte1: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_enc[15:8] == enc1_e
    );

    // Byte 2 of mix_out_enc matches formula.
    check_enc_byte2: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_enc[23:16] == enc2_e
    );

    // Byte 3 of mix_out_enc matches formula.
    check_enc_byte3: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_enc[31:24] == enc3_e
    );

    // mix_out_dec equals mix_out_enc XOR the replicated pattern derived from mix_in.
    check_dec_full: assert property (
        @(posedge CLK) disable iff (!RESETn) mix_out_dec == (mix_out_enc ^ patt32)
    );

    // The XOR difference between dec and enc has identical upper and lower 16-bit halves.
    check_diff_halves_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) diff[31:16] == diff[15:0]
    );

    // The XOR difference byte3 equals byte1 (replication).
    check_diff_byte_pair_high: assert property (
        @(posedge CLK) disable iff (!RESETn) diff[31:24] == diff[15:8]
    );

    // The XOR difference byte2 equals byte0 (replication).
    check_diff_byte_pair_low: assert property (
        @(posedge CLK) disable iff (!RESETn) diff[23:16] == diff[7:0]
    );

    // The low 16 bits of the XOR difference match the computed pattern from mix_in.
    check_diff_low_matches_pattern: assert property (
        @(posedge CLK) disable iff (!RESETn) diff[15:0] == patt16
    );

    // If mix_in is stable across a cycle, both outputs remain stable (pure combinational).
    check_outputs_stable_when_input_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable(mix_in) |-> ($stable(mix_out_enc) && $stable(mix_out_dec))
    );
endmodule

