module concat_module_sva (
    input logic clk,
    input logic [89:0] in,
    input logic [44:0] line0,
    input logic [44:0] line1,
    input logic [89:0] out
);
    ///// Register capture behavior /////
    // line0 captures the low 45 bits of 'in' from the previous cycle.
    check_line0_captures_low: assert property (
        @(posedge clk) line0 == $past(in[44:0])
    );
    // line1 captures the high 45 bits of 'in' from the previous cycle.
    check_line1_captures_high: assert property (
        @(posedge clk) line1 == $past(in[89:45])
    );

    ///// Output composition from previous cycle registers /////
    // out is the concatenation of the previous values of line0 (MSBs) and line1 (LSBs).
    check_out_from_prev_lines: assert property (
        @(posedge clk) out == $past({line0, line1})
    );
    // The MSBs of out come from the previous line0.
    check_out_msb_from_prev_line0: assert property (
        @(posedge clk) out[89:45] == $past(line0)
    );
    // The LSBs of out come from the previous line1.
    check_out_lsb_from_prev_line1: assert property (
        @(posedge clk) out[44:0] == $past(line1)
    );

    ///// Relation to previous input /////
    // out equals the previous input with halves swapped: {in_low, in_high}.
    check_out_equals_swapped_prev_in: assert property (
        @(posedge clk) out == { $past(in[44:0]), $past(in[89:45]) }
    );
    // The pair {line0,line1} reflects the previous input halves.
    check_lines_match_prev_in_halves: assert property (
        @(posedge clk) {line0, line1} == { $past(in[44:0]), $past(in[89:45]) }
    );

    ///// Change propagation /////
    // A change in the low half of 'in' causes line0 to change next cycle.
    check_low_in_change_propagates_to_line0: assert property (
        @(posedge clk) $changed(in[44:0]) |-> ##1 $changed(line0)
    );
    // A change in the high half of 'in' causes line1 to change next cycle.
    check_high_in_change_propagates_to_line1: assert property (
        @(posedge clk) $changed(in[89:45]) |-> ##1 $changed(line1)
    );
    // Any change in {line0,line1} causes out to change next cycle.
    check_lines_change_propagates_to_out: assert property (
        @(posedge clk) $changed({line0, line1}) |-> ##1 $changed(out)
    );
    // Any change in 'in' causes out to change next cycle (via swapped mapping).
    check_in_change_propagates_to_out: assert property (
        @(posedge clk) $changed(in) |-> ##1 $changed(out)
    );
    // If 'in' is stable across a cycle, out is stable on the next cycle.
    check_stable_in_keeps_out_stable_next: assert property (
        @(posedge clk) $stable(in) |-> ##1 $stable(out)
    );
endmodule

verilog_code:
module shift_register (
  input clk,
  input reset,
  input load,
  input [7:0] data_in,
  output [7:0] data_out
);

reg [7:0] shift_reg;

always @(posedge clk, negedge reset) begin
  if (!reset) begin
    shift_reg <= 8'b0;
  end else if (load) begin
    shift_reg <= data_in;
  end else begin
    shift_reg <= {shift_reg[6:0], shift_reg[7]};
  end
end

assign data_out = shift_reg;

endmodule

sva_code:
module shift_register_sva (
  input logic clk,
  input logic reset,
  input logic load,
  input logic [7:0] data_in,
  input logic [7:0] data_out
);

  ///// Reset behavior /////
  // While reset is asserted low, data_out must be zero.
  reset_clears_output: assert property (
    @(posedge clk) !reset |-> (data_out == 8'b0)
  );

  ///// Load behavior /////
  // When load is high, data_out updates to data_in in the same cycle.
  load_updates_immediately: assert property (
    @(posedge clk) disable iff (!reset) load |-> (data_out == data_in)
  );

  ///// Rotate behavior when not loading /////
  // When load is low, data_out rotates left by one bit from the previous value.
  rotate_one_step_vector: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out == { $past(data_out[6:0]), $past(data_out[7]) })
  );

  // Bit 7 takes previous bit 6 when not loading.
  rotate_bit7_from6: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out[7] == $past(data_out[6]))
  );

  // Bit 0 takes previous bit 7 when not loading.
  rotate_bit0_from7: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out[0] == $past(data_out[7]))
  );

  // Eight consecutive rotates return data_out to its value from eight cycles earlier.
  rotate_eight_cycle_identity: assert property (
    @(posedge clk) disable iff (!reset) (!load)[*8] |-> (data_out == $past(data_out, 8))
  );

  ///// Post-reset first-cycle behavior /////
  // On the first cycle after reset deasserts with no load, data_out remains zero.
  first_cycle_after_reset_no_load_zero: assert property (
    @(posedge clk) $rose(reset) && !load |-> (data_out == 8'b0)
  );

  // On the first cycle after reset deasserts with load, data_out equals data_in.
  first_cycle_after_reset_with_load_loads: assert property (
    @(posedge clk) $rose(reset) && load |-> (data_out == data_in)
  );

endmodule

verilog_code:
module mux2to1 (
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y
);

    wire A1 = ~A1_N;
    wire A2 = ~A2_N;

    assign Y = (A1 & A2 & B2) | (A1 & ~A2 & B1) | (~A1 & A2 & B2) | (~A1 & ~A2 & B1);

endmodule

sva_code:
module mux2to1_sva (
    input logic clk,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y
);
    // Local mirrors of RTL internal nets
    wire A1 = ~A1_N;
    wire A2 = ~A2_N;

    // Y implements the exact RTL sum-of-products expression.
    check_function_sop: assert property (
        @(posedge clk) Y == ((A1 & A2 & B2) | (A1 & ~A2 & B1) | (~A1 & A2 & B2) | (~A1 & ~A2 & B1))
    );

    // Y equals mux form: A2_N=1 selects B1, A2_N=0 selects B2.
    check_function_mux_form: assert property (
        @(posedge clk) Y == ((~A2_N & B2) | (A2_N & B1))
    );

    // When select is HIGH (A2_N=1), Y must equal B1.
    check_select_high_b1: assert property (
        @(posedge clk) (A2_N == 1'b1) |-> (Y == B1)
    );

    // When select is LOW (A2_N=0), Y must equal B2.
    check_select_low_b2: assert property (
        @(posedge clk) (A2_N == 1'b0) |-> (Y == B2)
    );

    // Changing A1_N alone must not change Y.
    check_a1n_no_effect: assert property (
        @(posedge clk) (!$initstate && $changed(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> (Y == $past(Y))
    );

    // If B1==B2, Y must equal that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (B1 == B2) |-> (Y == B1)
    );

    // Changing select with equal inputs must not change Y.
    check_no_change_on_sel_when_inputs_equal: assert property (
        @(posedge clk) (!$initstate && $changed(A2_N) && $stable(B1) && $stable(B2) && (B1 == B2)) |-> (Y == $past(Y))
    );

    // Changing select with different inputs must toggle Y.
    check_toggle_on_sel_when_inputs_differ: assert property (
        @(posedge clk) (!$initstate && $changed(A2_N) && $stable(B1) && $stable(B2) && (B1 != B2)) |-> (Y != $past(Y))
    );

    // With select HIGH, changing B1 alone must toggle Y.
    check_follow_b1_when_sel_high: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b1) && $changed(B1) && $stable(A2_N) && $stable(B2)) |-> (Y != $past(Y))
    );

    // With select LOW, changing B2 alone must toggle Y.
    check_follow_b2_when_sel_low: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b0) && $changed(B2) && $stable(A2_N) && $stable(B1)) |-> (Y != $past(Y))
    );

    // With select HIGH, changing B2 alone must not change Y.
    check_ignore_b2_when_sel_high: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b1) && $changed(B2) && $stable(A2_N) && $stable(B1)) |-> (Y == $past(Y))
    );

    // With select LOW, changing B1 alone must not change Y.
    check_ignore_b1_when_sel_low: assert property (
        @(posedge clk) (!$initstate && (A2_N == 1'b0) && $changed(B1) && $stable(A2_N) && $stable(B2)) |-> (Y == $past(Y))
    );
endmodule

verilog_code:
module edge_detector (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

reg [7:0] prev_in;
reg [7:0] edge_detected;

parameter IDLE = 2'b00;
parameter RISING_EDGE = 2'b01;
parameter FALLING_EDGE = 2'b10;

always @(posedge clk) begin
    case (prev_in ^ in)
        8'b00000001, 8'b00000010, 8'b00000100, 8'b00001000, 8'b00010000, 8'b00100000, 8'b01000000, 8'b10000000:
            edge_detected <= RISING_EDGE;
        8'b11111110, 8'b11111101, 8'b11111011, 8'b11110111, 8'b11101111, 8'b11011111, 8'b10111111, 8'b01111111:
            edge_detected <= FALLING_EDGE;
        default:
            edge_detected <= IDLE;
    endcase
    prev_in <= in;
end

assign anyedge = edge_detected;

endmodule

sva_code:
module edge_detector_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] anyedge
);

    ///// Output encoding constraints /////
    // anyedge can only be 8'h00 (IDLE), 8'h01 (RISING_EDGE code), or 8'h02 (FALLING_EDGE code).
    check_anyedge_value_set: assert property (
        @(posedge clk) anyedge inside {8'h00, 8'h01, 8'h02}
    );

    ///// Functional mapping from previous/current input difference /////
    // One-hot XOR between $past(in) and in selects 8'h01.
    check_onehot_xor_gives_01: assert property (
        @(posedge clk) $onehot($past(in) ^ in) |-> (anyedge == 8'h01)
    );

    // One-cold XOR (i.e., complement is one-hot) selects 8'h02.
    check_onecold_xor_gives_02: assert property (
        @(posedge clk) $onehot(~($past(in) ^ in)) |-> (anyedge == 8'h02)
    );

    // If XOR is neither one-hot nor one-cold, anyedge is 8'h00.
    check_default_gives_00: assert property (
        @(posedge clk) !($onehot($past(in) ^ in) || $onehot(~($past(in) ^ in))) |-> (anyedge == 8'h00)
    );

    ///// Useful special cases /////
    // If input does not change, anyedge is 8'h00.
    check_no_change_idle: assert property (
        @(posedge clk) ($past(in) == in) |-> (anyedge == 8'h00)
    );

    // If all bits toggle, anyedge is 8'h00 (falls into default case).
    check_all_bits_toggle_idle: assert property (
        @(posedge clk) (($past(in) ^ in) == 8'hFF) |-> (anyedge == 8'h00)
    );

    ///// Reverse implications (consistency) /////
    // anyedge == 8'h01 implies XOR was one-hot.
    check_01_implies_onehot: assert property (
        @(posedge clk) (anyedge == 8'h01) |-> $onehot($past(in) ^ in)
    );

    // anyedge == 8'h02 implies XOR was one-cold.
    check_02_implies_onecold: assert property (
        @(posedge clk) (anyedge == 8'h02) |-> $onehot(~($past(in) ^ in))
    );

    // anyedge == 8'h00 implies XOR was neither one-hot nor one-cold.
    check_00_implies_neither: assert property (
        @(posedge clk) (anyedge == 8'h00) |-> !($onehot($past(in) ^ in) || $onehot(~($past(in) ^ in)))
    );

    ///// Structural encoding /////
    // Upper 6 bits of anyedge are always zero due to 8'h00/01/02 assignments.
    check_upper_bits_zero: assert property (
        @(posedge clk) anyedge[7:2] == 6'b0
    );

endmodule

verilog_code:
module adder #(parameter WIDTH=8) (
    input clk, rst, load,
    input [WIDTH-1:0] A, B,
    output [WIDTH-1:0] Q
);

    wire [WIDTH:0] carry;
    wire [WIDTH-1:0] sum;

    // Ripple-carry adder
    genvar i;
    generate 
        for (i = 0; i < WIDTH; i = i + 1) begin : adder_stage
            full_adder FA (
                .a(A[i]), .b(B[i]), .c(carry[i]),
                .sum(sum[i]), .carry(carry[i+1])
            );
        end
    endgenerate

    // Carry-out for the last stage
    assign carry[WIDTH] = (A[WIDTH-1] & B[WIDTH-1]) | (A[WIDTH-1] & carry[WIDTH-1]) | (B[WIDTH-1] & carry[WIDTH-1]);

    // Registering the output
    reg [WIDTH-1:0] Q_reg;
    always @(posedge clk) begin
        if (rst) begin
            Q_reg <= 0;
        end else if (load) begin
            Q_reg <= sum;
        end
    end

    assign Q = Q_reg;

    assign carry[0] = 0; // Connect the first carry-in to 0.

endmodule
module full_adder (
    input a, b, c,
    output sum, carry
);

    assign sum = a ^ b ^ c;
    assign carry = (a & b) | (a & c) | (b & c);

endmodule

sva_code:
module adder_sva #(parameter WIDTH=8) (
    input logic clk,
    input logic rst,       // Active-high synchronous reset
    input logic load,
    input logic [WIDTH-1:0] A,
    input logic [WIDTH-1:0] B,
    input logic [WIDTH-1:0] Q
);

    ///// Reset behavior /////
    // One cycle after rst is asserted, Q must be zero.
    check_reset_clears_q_next: assert property (
        @(posedge clk) rst |=> (Q == '0)
    );

    // If rst is asserted in consecutive cycles, Q is zero in the later cycle.
    check_in_reset_q_zero_current: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (Q == '0)
    );

    // Reset has priority over load; if both high, Q still clears to zero next cycle.
    check_reset_overrides_load: assert property (
        @(posedge clk) (rst && load) |=> (Q == '0)
    );

    ///// Sequential update semantics /////
    // Without load (and not coming from reset), Q holds its previous value.
    check_hold_without_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && !$past(load) && !$past(rst)) |-> (Q == $past(Q))
    );

    // Q only changes when the previous cycle had load or reset.
    check_change_requires_load_or_reset: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && (Q != $past(Q))) |-> ($past(load) || $past(rst))
    );

    ///// Functional correctness /////
    // After a load (and not from reset), Q equals A+B modulo WIDTH from the load cycle.
    check_sum_update_correct: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && $past(load) && !$past(rst)) |-> (Q == (($past(A) + $past(B)) [WIDTH-1:0]))
    );

    // LSB correctness after load: carry-in to bit 0 is 0, so Q[0] = A[0] ^ B[0].
    check_lsb_after_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && $past(load) && !$past(rst)) |-> (Q[0] == ($past(A[0]) ^ $past(B[0])))
    );

    // If load stays low for two consecutive cycles (no reset), Q remains constant across them.
    check_two_cycle_hold_no_load: assert property (
        @(posedge clk) disable iff (rst)
            ($past(1'b1) && !$past(load) && !load && !$past(rst)) |-> (Q == $past(Q))
    );

endmodule

verilog_code:
module diff_module(
  input [3:0] A,
  input [3:0] B,
  input C,
  output reg [4:0] diff
);

  always @(*) begin
    diff = A - B;
    if (C == 1'b1) begin
      diff = ~diff + 1'b1;
    end
  end

endmodule

sva_code:
module diff_module_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C,
    input logic [4:0] diff
);
    // When C=0, diff equals zero-extended 4-bit (A-B).
    check_diff_when_C0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (diff == {1'b0, (A - B)})
    );

    // When C=1, diff equals two's complement of zero-extended 4-bit (A-B).
    check_diff_when_C1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (diff == ((~{1'b0, (A - B)}) + 5'd1))
    );

    // When C=0, the MSB of diff must be 0.
    check_msb_zero_when_C0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (diff[4] == 1'b0)
    );

    // For any C, if A==B then diff must be 0.
    check_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A == B) |-> (diff == 5'd0)
    );

    // For any C, diff==0 implies A==B.
    check_zero_implies_inputs_equal: assert property (
        @(posedge CLK) (diff == 5'd0) |-> (A == B)
    );

    // When C=1 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C1: assert property (
        @(posedge CLK) (C == 1'b1 && (A != B)) |-> (diff != 5'd0)
    );

    // When C=1 and A!=B, diff MSB must be 1.
    check_msb_one_when_C1_and_notequal: assert property (
        @(posedge CLK) (C == 1'b1 && (A != B)) |-> (diff[4] == 1'b1)
    );

    // When C rises and A,B are stable, diff is two's complement of previous diff.
    check_twos_complement_on_C_rise: assert property (
        @(posedge CLK) ($rose(C) && A == $past(A) && B == $past(B)) |-> (diff == ((~$past(diff)) + 5'd1))
    );

    // When C falls and A,B are stable, diff is two's complement of previous diff.
    check_twos_complement_on_C_fall: assert property (
        @(posedge CLK) ($fell(C) && A == $past(A) && B == $past(B)) |-> (diff == ((~$past(diff)) + 5'd1))
    );

    // When C=0 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C0: assert property (
        @(posedge CLK) (C == 1'b0 && (A != B)) |-> (diff != 5'd0)
    );
endmodule

module up_down_counter_sva (
    input  logic [3:0] LOAD,
    input  logic       UP_DOWN,
    input  logic       CLK,
    input  logic       RESET,
    input  logic [3:0] COUNT
);
    ///// Reset behavior /////
    // While RESET is asserted, COUNT must be 0.
    check_reset_clears_count: assert property (
        @(posedge CLK) RESET |-> (COUNT == 4'd0)
    );

    ///// Load behavior /////
    // On non-zero LOAD, COUNT is updated to LOAD on the next clock.
    check_load_updates_count: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD != 4'd0) |=> (RESET || (COUNT == $past(LOAD)))
    );

    ///// Counting behavior /////
    // With LOAD == 0 and UP_DOWN == 1, COUNT increments by 1 on the next clock.
    check_increment_when_up: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b1)) |=> (RESET || (COUNT == ($past(COUNT) + 4'd1)))
    );

    // With LOAD == 0 and UP_DOWN == 0, COUNT decrements by 1 on the next clock.
    check_decrement_when_down: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b0)) |=> (RESET || (COUNT == ($past(COUNT) - 4'd1)))
    );

    ///// Wrap-around checks /////
    // Incrementing from 4'hF wraps to 4'h0 when LOAD == 0 and UP_DOWN == 1.
    check_wrap_on_increment: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b1) && ($past(COUNT) == 4'hF)) |=> (RESET || (COUNT == 4'h0))
    );

    // Decrementing from 4'h0 wraps to 4'hF when LOAD == 0 and UP_DOWN == 0.
    check_wrap_on_decrement: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b0) && ($past(COUNT) == 4'h0)) |=> (RESET || (COUNT == 4'hF))
    );
endmodule

