               a3(.S(S[2]), .Cout(c3), .A(A[2]), .B(B[2]), .Cin(c2)),
               a4(.S(S[3]), .Cout(Cout), .A(A[3]), .B(B[3]), .Cin(c3));

endmodule

module full_adder(output S, output Cout, input A, B, input Cin);
    assign {Cout, S} = A + B + Cin;
endmodule

