module comparator_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [1:0] out
);
    ///// Combinational mapping checks /////
    // When in1 equals in2, out must be 2'b00.
    map_eq: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 2'b00)
    );
    // When in1 is greater than in2, out must be 2'b01.
    map_gt: assert property (
        @(posedge clk) (in1 > in2) |-> (out == 2'b01)
    );
    // When in1 is less than in2, out must be 2'b10.
    map_lt: assert property (
        @(posedge clk) (in1 < in2) |-> (out == 2'b10)
    );

    ///// Reverse mapping (code implies relation) /////
    // If out is 2'b00, inputs must be equal.
    rev_map_eq: assert property (
        @(posedge clk) (out == 2'b00) |-> (in1 == in2)
    );
    // If out is 2'b01, in1 must be greater than in2.
    rev_map_gt: assert property (
        @(posedge clk) (out == 2'b01) |-> (in1 > in2)
    );
    // If out is 2'b10, in1 must be less than in2.
    rev_map_lt: assert property (
        @(posedge clk) (out == 2'b10) |-> (in1 < in2)
    );

    ///// Encoding sanity /////
    // out must never be 2'b11.
    out_never_illegal_11: assert property (
        @(posedge clk) out != 2'b11
    );

    ///// Stability relationships /////
    // If inputs are stable across a cycle, out must be stable.
    output_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(in1) && $stable(in2)) |-> $stable(out)
    );
    // If out changes, at least one input must have changed.
    out_change_requires_input_change: assert property (
        @(posedge clk) $changed(out) |-> ($changed(in1) || $changed(in2))
    );
endmodule

verilog_code:
module pipeline_register(
    input clock,
    input reset,
    input IF_Flush,
    input IF_Stall,
    input ID_Stall,
    input [31:0] IF_Instruction,
    input [31:0] IF_PCAdd4,
    input [31:0] IF_PC,
    input IF_IsBDS,
    input [31:0] ID_Instruction,
    input [31:0] ID_PCAdd4,
    input [31:0] ID_RestartPC,
    input ID_IsBDS,
    input ID_IsFlushed,
    output reg [31:0] vote_ID_Instruction,
    output reg [31:0] vote_ID_PCAdd4,
    output reg [31:0] vote_ID_RestartPC,
    output reg vote_ID_IsBDS,
    output reg vote_ID_IsFlushed
);

    always @(posedge clock) begin
        if (reset) begin
            vote_ID_Instruction <= 32'b0;
            vote_ID_PCAdd4 <= 32'b0;
            vote_ID_RestartPC <= 32'b0;
            vote_ID_IsBDS <= 1'b0;
            vote_ID_IsFlushed <= 1'b0;
        end else begin
            if (ID_Stall) begin
                vote_ID_Instruction <= ID_Instruction;
                vote_ID_PCAdd4 <= ID_PCAdd4;
                vote_ID_IsBDS <= ID_IsBDS;
                vote_ID_RestartPC <= ID_RestartPC;
                vote_ID_IsFlushed <= ID_IsFlushed;
            end else begin
                if (IF_Stall | IF_Flush) begin
                    vote_ID_Instruction <= 32'b0;
                    vote_ID_PCAdd4 <= 32'b0;
                end else begin
                    vote_ID_Instruction <= IF_Instruction;
                    vote_ID_PCAdd4 <= IF_PCAdd4;
                end
                if (ID_IsFlushed | IF_IsBDS) begin
                    vote_ID_RestartPC <= ID_RestartPC;
                end else begin
                    vote_ID_RestartPC <= IF_PC;
                end
                vote_ID_IsBDS <= ID_IsBDS;
                vote_ID_IsFlushed <= ID_IsFlushed;
            end
        end
    end

endmodule

sva_code:
module pipeline_register_sva (
    input logic clock,
    input logic reset,
    input logic IF_Flush,
    input logic IF_Stall,
    input logic ID_Stall,
    input logic [31:0] IF_Instruction,
    input logic [31:0] IF_PCAdd4,
    input logic [31:0] IF_PC,
    input logic IF_IsBDS,
    input logic [31:0] ID_Instruction,
    input logic [31:0] ID_PCAdd4,
    input logic [31:0] ID_RestartPC,
    input logic ID_IsBDS,
    input logic ID_IsFlushed,
    input logic [31:0] vote_ID_Instruction,
    input logic [31:0] vote_ID_PCAdd4,
    input logic [31:0] vote_ID_RestartPC,
    input logic vote_ID_IsBDS,
    input logic vote_ID_IsFlushed
);
    // On reset, all outputs clear to zero on the next cycle.
    reset_clears_outputs: assert property (
        @(posedge clock) reset |=> (vote_ID_Instruction == 32'b0)
                            && (vote_ID_PCAdd4 == 32'b0)
                            && (vote_ID_RestartPC == 32'b0)
                            && (vote_ID_IsBDS == 1'b0)
                            && (vote_ID_IsFlushed == 1'b0)
    );

    // When ID_Stall is asserted, data fields capture from ID_* on the next cycle.
    id_stall_captures_id_data: assert property (
        @(posedge clock) disable iff (reset)
            ID_Stall |=> (vote_ID_Instruction == $past(ID_Instruction))
                      && (vote_ID_PCAdd4    == $past(ID_PCAdd4))
                      && (vote_ID_RestartPC == $past(ID_RestartPC))
    );

    // When !ID_Stall and IF_Stall or IF_Flush, instruction and PCAdd4 zero on next cycle.
    zero_if_fields_on_if_stall_or_flush: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == 32'b0)
                                                  && (vote_ID_PCAdd4 == 32'b0)
    );

    // When !ID_Stall and no IF_Stall/Flush, instruction and PCAdd4 pass through from IF_*.
    pass_if_fields_when_no_if_controls: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == $past(IF_Instruction))
                                                   && (vote_ID_PCAdd4    == $past(IF_PCAdd4))
    );

    // When !ID_Stall and (ID_IsFlushed or IF_IsBDS), RestartPC comes from ID_RestartPC.
    restartpc_selects_id_on_flush_or_bds: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(ID_RestartPC))
    );

    // When !ID_Stall and not (ID_IsFlushed or IF_IsBDS), RestartPC comes from IF_PC.
    restartpc_selects_if_on_normal_flow: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(IF_PC))
    );

    // vote_ID_IsBDS always reflects prior-cycle ID_IsBDS (outside reset).
    flags_follow_id_isbds: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsBDS == $past(ID_IsBDS))
    );

    // vote_ID_IsFlushed always reflects prior-cycle ID_IsFlushed (outside reset).
    flags_follow_id_isflushed: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsFlushed == $past(ID_IsFlushed))
    );
endmodule

module counter_with_load_reset_sva (
    input  logic [3:0] DATA_IN,
    input  logic       LOAD,
    input  logic       CLK,
    input  logic       RESET,
    input  logic [3:0] COUNT
);
    ///// Reset behavior /////
    // When RESET is asserted low, COUNT must be 0.
    check_reset_drives_zero: assert property (
        @(posedge CLK) (!RESET) |-> (COUNT == 4'd0)
    );

    ///// Next-state behavior /////
    // General next-state: after a non-reset cycle, COUNT matches LOAD/Data/Inc from previous cycle.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) |-> COUNT == ($past(LOAD) ? $past(DATA_IN) : (($past(COUNT) + 4'd1) & 4'hF))
    );

    // LOAD=1 loads DATA_IN on the next cycle.
    check_load_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) |-> (COUNT == $past(DATA_IN))
    );

    // LOAD=0 increments COUNT by 1 modulo 16 on the next cycle.
    check_increment_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT == (($past(COUNT) + 4'd1) & 4'hF))
    );

    // LOAD=0 causes COUNT to change (it cannot hold its value).
    check_increment_changes_value: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT != $past(COUNT))
    );

    // With LOAD=0 and COUNT at 15, next COUNT wraps to 0.
    check_wrap_on_max_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) && ($past(COUNT) == 4'hF) |-> (COUNT == 4'h0)
    );

    // If LOAD=1, the load path has priority over increment (distinct from +1 result).
    check_load_priority_over_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) &&
            ($past(DATA_IN) != (($past(COUNT) + 4'd1) & 4'hF)) |-> (COUNT != (($past(COUNT) + 4'd1) & 4'hF))
    );

    // Two consecutive cycles with LOAD=0 increment COUNT by 2 modulo 16.
    check_two_cycle_increment_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && !$past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(COUNT,2) + 4'd2) & 4'hF)
    );

    // LOAD followed by no LOAD results in DATA_IN+1 on the second cycle (modulo 16).
    check_load_then_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && $past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(DATA_IN,2) + 4'd1) & 4'hF)
    );
endmodule

verilog_code:
module xor_inv_multiplexer (
    input clk,
    input [3:0] a,
    input [3:0] b,
    input sel_b1,
    input sel_b2,
    input sel_out,
    output reg out_always,
    output [3:0] out_xor,
    output [3:0] out_xor_inv,
    output out_logical_inv
);

    // Intermediate wires to store the selected input
    wire [3:0] selected_input_b1;
    wire [3:0] selected_input_b2;

    // 2-to-1 multiplexer to select between a and b
    assign selected_input_b1 = sel_b1 ? b : a;

    // 2-to-1 multiplexer to select between selected_input_b1 and b
    assign selected_input_b2 = sel_b2 ? b : selected_input_b1;

    // XOR and inverter operations on the selected input
    assign out_xor = selected_input_b2 ^ a;
    assign out_xor_inv = ~out_xor;
    assign out_logical_inv = !out_xor;

    // 2-to-1 multiplexer to select between XOR and logical inverse outputs
    always @(posedge clk) begin
        if (sel_out) begin
            out_always <= out_logical_inv;
        end else begin
            out_always <= out_xor_inv;
        end
    end

endmodule

