    check_sum_low_slice_match: assert property (
        @(posedge CLK) sum_low == sum[15:0]
    );
    // sum_high matches high 16 bits of sum.
    check_sum_high_slice_match: assert property (
        @(posedge CLK) sum_high == sum[31:16]
    );
