sva_code:
module xor3_1_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // X equals A ^ B ^ C when sampled on A rising edge.
    check_xor_eq_on_A: assert property (
        @(posedge A) X == (A ^ B ^ C)
    );

    // X equals A ^ B ^ C when sampled on B rising edge.
    check_xor_eq_on_B: assert property (
        @(posedge B) X == (A ^ B ^ C)
    );

    // X equals A ^ B ^ C when sampled on C rising edge.
    check_xor_eq_on_C: assert property (
        @(posedge C) X == (A ^ B ^ C)
    );

    // With B=0 and C=0, X follows A.
    check_B0_C0_eq_A: assert property (
        @(posedge A) (B == 1'b0 && C == 1'b0) |-> (X == A)
    );

    // With B=1 and C=1, X follows A.
    check_B1_C1_eq_A: assert property (
        @(posedge A) (B == 1'b1 && C == 1'b1) |-> (X == A)
    );

    // With B=1 and C=0, X equals bitwise NOT of A.
    check_B1_C0_eq_notA: assert property (
        @(posedge B) (B == 1'b1 && C == 1'b0) |-> (X == ~A)
    );

    // With B=0 and C=1, X equals bitwise NOT of A.
    check_B0_C1_eq_notA: assert property (
        @(posedge C) (B == 1'b0 && C == 1'b1) |-> (X == ~A)
    );

    // If A equals B, then X equals C.
    check_AeqB_implies_XeqC: assert property (
        @(posedge A) (A == B) |-> (X == C)
    );

    // If B equals C, then X equals A.
    check_BeqC_implies_XeqA: assert property (
        @(posedge B) (B == C) |-> (X == A)
    );

    // If A equals C, then X equals B.
    check_AeqC_implies_XeqB: assert property (
        @(posedge C) (A == C) |-> (X == B)
    );
endmodule

module ones_counter_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [2:0] b
);
    ///// Direct implementation checks /////
    // b[2] equals ~(a3&a2&a1&a0).
    check_b2_definition: assert property (
        @(posedge CLK) b[2] == ~(a[3] & a[2] & a[1] & a[0])
    );
    // b[1] equals conjunction of negated 3-one minterms.
    check_b1_definition: assert property (
        @(posedge CLK) b[1] == ( ~(a[3] & a[2] & a[1] & ~a[0])
                               & ~(a[3] & a[2] & ~a[1] & a[0])
                               & ~(a[3] & ~a[2] & a[1] & a[0])
                               & ~(~a[3] & a[2] & a[1] & a[0]) )
    );
    // b[0] equals conjunction of negated 2-one minterms and negated 4-ones.
    check_b0_definition: assert property (
        @(posedge CLK) b[0] == ( ~(a[3] & a[2] & ~a[1] & ~a[0])
                               & ~(a[3] & ~a[2] & a[1] & ~a[0])
                               & ~(a[3] & ~a[2] & ~a[1] & a[0])
                               & ~(~a[3] & a[2] & a[1] & ~a[0])
                               & ~(~a[3] & a[2] & ~a[1] & a[0])
                               & ~(~a[3] & ~a[2] & a[1] & a[0])
                               & ~(a[3] & a[2] & a[1] & a[0]) )
    );

    ///// Input pattern to output mapping /////
    // For a==4'b1111, b==3'b010.
    check_all_ones_output: assert property (
        @(posedge CLK) (a[3] & a[2] & a[1] & a[0]) |-> (b == 3'b010)
    );
    // For exactly three ones, b==3'b101.
    check_three_ones_output: assert property (
        @(posedge CLK)
        ( (a[3] & a[2] & a[1] & ~a[0])
        | (a[3] & a[2] & ~a[1] & a[0])
        | (a[3] & ~a[2] & a[1] & a[0])
        | (~a[3] & a[2] & a[1] & a[0]) ) |-> (b == 3'b101)
    );
    // For exactly two ones, b==3'b110.
    check_two_ones_output: assert property (
        @(posedge CLK)
        ( (a[3] & a[2] & ~a[1] & ~a[0])
        | (a[3] & ~a[2] & a[1] & ~a[0])
        | (a[3] & ~a[2] & ~a[1] & a[0])
        | (~a[3] & a[2] & a[1] & ~a[0])
        | (~a[3] & a[2] & ~a[1] & a[0])
        | (~a[3] & ~a[2] & a[1] & a[0]) ) |-> (b == 3'b110)
    );
    // For zero or one '1' in a, b==3'b111.
    check_zero_or_one_ones_output: assert property (
        @(posedge CLK)
        !( (a[3] & a[2] & ~a[1] & ~a[0])
         | (a[3] & ~a[2] & a[1] & ~a[0])
         | (a[3] & ~a[2] & ~a[1] & a[0])
         | (~a[3] & a[2] & a[1] & ~a[0])
         | (~a[3] & a[2] & ~a[1] & a[0])
         | (~a[3] & ~a[2] & a[1] & a[0])
         | (a[3] & a[2] & a[1] & a[0])
         | (a[3] & a[2] & a[1] & ~a[0])
         | (a[3] & a[2] & ~a[1] & a[0])
         | (a[3] & ~a[2] & a[1] & a[0])
         | (~a[3] & a[2] & a[1] & a[0]) ) |-> (b == 3'b111)
    );

    ///// Output-to-input consistency (only when possible) /////
    // b[2]==0 only when a==4'b1111.
    check_b2_zero_means_all_ones: assert property (
        @(posedge CLK) (b[2] == 1'b0) |-> (a[3] & a[2] & a[1] & a[0])
    );
    // b[1]==0 only when exactly three ones.
    check_b1_zero_means_three_ones: assert property (
        @(posedge CLK)
        (b[1] == 1'b0) |-> ( (a[3] & a[2] & a[1] & ~a[0])
                           | (a[3] & a[2] & ~a[1] & a[0])
                           | (a[3] & ~a[2] & a[1] & a[0])
                           | (~a[3] & a[2] & a[1] & a[0]) )
    );
    // b[0]==0 only when exactly two ones or four ones.
    check_b0_zero_means_two_or_four_ones: assert property (
        @(posedge CLK)
        (b[0] == 1'b0) |-> ( (a[3] & a[2] & ~a[1] & ~a[0])
                           | (a[3] & ~a[2] & a[1] & ~a[0])
                           | (a[3] & ~a[2] & ~a[1] & a[0])
                           | (~a[3] & a[2] & a[1] & ~a[0])
                           | (~a[3] & a[2] & ~a[1] & a[0])
                           | (~a[3] & ~a[2] & a[1] & a[0])
                           | (a[3] & a[2] & a[1] & a[0]) )
    );
endmodule

verilog_code:
module adder (
    input  [7:0] A,
    input  [7:0] B,
    output [7:0] C,
    output       CARRY
);

  wire [7:0] sum;
  wire       carry;

  assign {carry, sum} = A + B;

  assign CARRY = carry;
  assign C    = sum;

endmodule

sva_code:
module adder_sva (
    input  logic        CLK,
    input  logic [7:0]  A,
    input  logic [7:0]  B,
    input  logic [7:0]  C,
    input  logic        CARRY
);
    // Outputs equal full 9-bit unsigned sum of inputs.
    check_full_sum_equivalence: assert property (
        @(posedge CLK) {CARRY, C} == ({1'b0, A} + {1'b0, B})
    );
    // C equals the low 8 bits of A+B.
    check_c_low8: assert property (
        @(posedge CLK) C == (({1'b0, A} + {1'b0, B})[7:0])
    );
    // CARRY equals the 9th bit of A+B.
    check_carry_msb: assert property (
        @(posedge CLK) CARRY == (({1'b0, A} + {1'b0, B})[8])
    );
    // When A is zero, output mirrors B and carry is zero.
    check_when_A_zero: assert property (
        @(posedge CLK) (A == 8'h00) |-> (C == B) && (CARRY == 1'b0)
    );
    // When B is zero, output mirrors A and carry is zero.
    check_when_B_zero: assert property (
        @(posedge CLK) (B == 8'h00) |-> (C == A) && (CARRY == 1'b0)
    );
    // When A is 0xFF, C = B-1 and carry reflects B!=0.
    check_when_A_ff: assert property (
        @(posedge CLK) (A == 8'hFF) |-> (C == (B - 8'h01)) && (CARRY == (B != 8'h00))
    );
    // When B is 0xFF, C = A-1 and carry reflects A!=0.
    check_when_B_ff: assert property (
        @(posedge CLK) (B == 8'hFF) |-> (C == (A - 8'h01)) && (CARRY == (A != 8'h00))
    );
    // No overflow implies result is at least each operand.
    check_no_overflow_ge_operands: assert property (
        @(posedge CLK) (!CARRY) |-> (C >= A) && (C >= B)
    );
    // Overflow implies result is less than both operands.
    check_overflow_lt_operands: assert property (
        @(posedge CLK) (CARRY) |-> (C < A) && (C < B)
    );
    // LSB of sum equals XOR of operand LSBs (no carry-in).
    check_lsb_xor: assert property (
        @(posedge CLK) C[0] == (A[0] ^ B[0])
    );
endmodule

verilog_code:
module Key
(	input clk,
	input rst,

	input left,
	input right,
	input up,
	input down,

	output reg[7:0] direction
);

	reg [31:0]clk_cnt;
	reg left_key_last;
	reg right_key_last;
	reg up_key_last;
	reg down_key_last;

	always@(posedge clk or negedge rst) begin
		if(!rst) begin
			clk_cnt <= 0;
			direction <= 8'b0;

			left_key_last <= 0;
			right_key_last <= 0;
			up_key_last <= 0;
			down_key_last <= 0;					
		end	
		else begin
			if(clk_cnt == 5_0000) begin
				clk_cnt <= 0;
				left_key_last <= left;
				right_key_last <= right;
				up_key_last <= up;
				down_key_last <= down;

				if(left_key_last == 0 && left == 1) 
					direction <= 8'b0000_0001;
				if(right_key_last == 0 && right == 1)
					direction <= 8'b0000_0010;
				if(up_key_last == 0 && up == 1)
					direction <= 8'b0000_0011;
				if(down_key_last == 0 && down == 1)
					direction <= 8'b0000_0100;
			end						
			else begin
				clk_cnt <= clk_cnt + 1;
				direction <= 8'b0000_0000;
			end
		end	
	end				
endmodule

sva_code:
module Key_sva (
    input  logic        clk,
    input  logic        rst,
    input  logic        left,
    input  logic        right,
    input  logic        up,
    input  logic        down,
    input  logic [7:0]  direction,
    input  logic [31:0] clk_cnt,
    input  logic        left_key_last,
    input  logic        right_key_last,
    input  logic        up_key_last,
    input  logic        down_key_last
);
    ///// Reset behavior /////
    // While rst is LOW, all registers/outputs must be 0.
    reset_values: assert property (
        @(posedge clk) !rst |-> (clk_cnt == 32'd0) && (direction == 8'b0000_0000) &&
                         (left_key_last == 1'b0) && (right_key_last == 1'b0) &&
                         (up_key_last == 1'b0) && (down_key_last == 1'b0)
    );

    ///// Counter behavior /////
    // When not at limit, clk_cnt increments by 1 on the next cycle.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt != 32'd50000) |=> (clk_cnt == $past(clk_cnt) + 32'd1)
    );
    // When at limit, clk_cnt wraps to 0 on the next cycle.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (clk_cnt == 32'd0)
    );

    ///// Key last-value capture at sample /////
    // At sample, left_key_last captures current left on next cycle.
    capture_left_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (left_key_last == $past(left))
    );
    // At sample, right_key_last captures current right on next cycle.
    capture_right_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (right_key_last == $past(right))
    );
    // At sample, up_key_last captures current up on next cycle.
    capture_up_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (up_key_last == $past(up))
    );
    // At sample, down_key_last captures current down on next cycle.
    capture_down_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (down_key_last == $past(down))
    );

    ///// Direction encoding and timing /////
    // direction only takes values 0,1,2,3,4.
    check_direction_encoding: assert property (
        @(posedge clk) disable iff (!rst) direction inside {
            8'b0000_0000, 8'b0000_0001, 8'b0000_0010, 8'b0000_0011, 8'b0000_0100
        }
    );
    // A non-zero direction is a one-cycle pulse (next cycle observed as zero).
    direction_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (!rst) (direction != 8'b0000_0000) |=> (direction == 8'b0000_0000)
    );
    // Non-zero direction implies previous cycle was a sample with at least one rising key.
    direction_implies_prior_edge: assert property (
        @(posedge clk) disable iff (!rst)
            (direction != 8'b0000_0000) |->
            ($past(clk_cnt) == 32'd50000) &&
            (
                (($past(left_key_last)  == 1'b0) && ($past(left)  == 1'b1)) ||
                (($past(right_key_last) == 1'b0) && ($past(right) == 1'b1)) ||
                (($past(up_key_last)    == 1'b0) && ($past(up)    == 1'b1)) ||
                (($past(down_key_last)  == 1'b0) && ($past(down)  == 1'b1))
            )
    );

    ///// Direction priority on simultaneous edges (down > up > right > left) /////
    // If down rises at sample, next observed direction is 4.
    dir_on_down_rise: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) && (down_key_last == 1'b0) && (down == 1'b1)
            |=> (direction == 8'b0000_0100)
    );
    // If up rises (and down does not) at sample, next observed direction is 3.
    dir_on_up_rise_no_down: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (up_key_last == 1'b0) && (up == 1'b1) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0011)
    );
    // If right rises (and up/down do not) at sample, next observed direction is 2.
    dir_on_right_rise_no_up_down: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (right_key_last == 1'b0) && (right == 1'b1) &&
            !((up_key_last == 1'b0) && (up == 1'b1)) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0010)
    );
    // If left rises (and right/up/down do not) at sample, next observed direction is 1.
    dir_on_left_rise_no_others: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (left_key_last == 1'b0) && (left == 1'b1) &&
            !((right_key_last == 1'b0) && (right == 1'b1)) &&
            !((up_key_last == 1'b0) && (up == 1'b1)) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0001)
    );
endmodule

module dffr_sva (
    input logic C,
    input logic R,
    input logic D,
    input logic Q
);
    // Clock: C (posedge). Async reset: R (active-high). Q<=0 on posedge R; else Q<=D on posedge C when !R.

    // Async reset drives Q low immediately on R rising edge.
    check_async_reset_immediate_to_zero: assert property (
        @(posedge R) (Q == 1'b0)
    );

    // On C edge, if reset is high, Q must be 0 (reset dominates).
    check_reset_dominates_clocked_update: assert property (
        @(posedge C) R |-> (Q == 1'b0)
    );

    // While reset is held across consecutive C edges, Q remains 0 and stable.
    check_zero_stable_during_held_reset: assert property (
        @(posedge C) (R && $past(R)) |-> ((Q == 1'b0) && ($past(Q) == 1'b0))
    );

    // On the first C edge after reset deasserts, Q is still 0 before capturing new D.
    check_q_zero_on_cycle_after_reset_release: assert property (
        @(posedge C) disable iff (R) ($past(R) && !R) |-> (Q == 1'b0)
    );

    // Q can be high only when not in reset.
    check_q_one_only_when_not_in_reset: assert property (
        @(posedge C) disable iff (R) (Q == 1'b1) |-> (!R)
    );
endmodule

verilog_code:
module and_nand (
    Y,
    A1,
    A2,
    A3,
    B1,
    B2
);

    // Module ports
    output Y;
    input A1;
    input A2;
    input A3;
    input B1;
    input B2;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    // Local signals
    wire nand0_out;
    wire nand1_out;

    // NAND gates
    nand nand0 (nand0_out, A1, A2, A3);
    nand nand1 (nand1_out, B1, B2);

    // AND gate
    assign Y = nand0_out & nand1_out;

endmodule

sva_code:
module and_nand_sva (
    input logic CLK,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic nand0_out,
    input logic nand1_out
);
    // Y is the AND of the two NAND outputs.
    check_y_is_and_of_nands: assert property (
        @(posedge CLK) Y == (nand0_out & nand1_out)
    );

    // nand0_out implements ~(A1 & A2 & A3).
    check_nand0_function: assert property (
        @(posedge CLK) nand0_out == ~(A1 & A2 & A3)
    );

    // nand1_out implements ~(B1 & B2).
    check_nand1_function: assert property (
        @(posedge CLK) nand1_out == ~(B1 & B2)
    );

    // nand0_out is LOW when all A inputs are HIGH.
    check_nand0_low_when_all_ones: assert property (
        @(posedge CLK) (A1 & A2 & A3) |-> (nand0_out == 1'b0)
    );

    // nand0_out is HIGH when any A input is LOW.
    check_nand0_high_when_any_zero: assert property (
        @(posedge CLK) ((!A1) || (!A2) || (!A3)) |-> (nand0_out == 1'b1)
    );

    // nand1_out is LOW when both B inputs are HIGH.
    check_nand1_low_when_all_ones: assert property (
        @(posedge CLK) (B1 & B2) |-> (nand1_out == 1'b0)
    );

    // nand1_out is HIGH when any B input is LOW.
    check_nand1_high_when_any_zero: assert property (
        @(posedge CLK) ((!B1) || (!B2)) |-> (nand1_out == 1'b1)
    );

    // Y is LOW when all A inputs are HIGH.
    check_y_low_when_a_all_ones: assert property (
        @(posedge CLK) (A1 & A2 & A3) |-> (Y == 1'b0)
    );

    // Y is LOW when both B inputs are HIGH.
    check_y_low_when_b_all_ones: assert property (
        @(posedge CLK) (B1 & B2) |-> (Y == 1'b0)
    );

    // Y is HIGH when at least one A is LOW and at least one B is LOW.
    check_y_high_when_both_groups_have_zero: assert property (
        @(posedge CLK) (((!A1) || (!A2) || (!A3)) && ((!B1) || (!B2))) |-> (Y == 1'b1)
    );

    // Y matches the combined boolean function ~(A1&A2&A3) & ~(B1&B2).
    check_y_matches_boolean_function: assert property (
        @(posedge CLK) Y == ((~(A1 & A2 & A3)) & (~(B1 & B2)))
    );
endmodule

module and_gate_sva (
    input logic A,
    input logic B,
    input logic clk,
    input logic reset,   // Active-high synchronous reset
    input logic X
);

    // When previous cycle was not reset, X equals previous A & B.
    check_next_matches_prev_and: assert property (
        @(posedge clk) disable iff (reset || $initstate) !$past(reset) |-> (X == $past(A & B))
    );

    // If previous cycle was reset, X must be 0 now.
    reset_prev_cycle_forces_zero: assert property (
        @(posedge clk) disable iff ($initstate) $past(reset) |-> (X == 1'b0)
    );

    // If reset is asserted now, X must be 0 on the next cycle.
    reset_now_forces_zero_next: assert property (
        @(posedge clk) disable iff ($initstate) reset |-> (X == 1'b0)
    );

    // While reset stays asserted across cycles, X must be 0.
    hold_zero_during_continuous_reset: assert property (
        @(posedge clk) disable iff ($initstate) (reset && $past(reset)) |-> (X == 1'b0)
    );

    // If prev A=1 and prev B=1 and not in reset prev cycle, X must be 1 now.
    prev_inputs_both_one_yield_one: assert property (
        @(posedge clk) disable iff (reset || $initstate) (!$past(reset) && $past(A) && $past(B)) |-> (X == 1'b1)
    );

    // If either prev A=0 or prev B=0 and not in reset prev cycle, X must be 0 now.
    prev_input_zero_yields_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate) (!$past(reset) && (!$past(A) || !$past(B))) |-> (X == 1'b0)
    );

    // If X is 1 now and not in reset prev cycle, then both prev A and prev B were 1.
    x_one_requires_prev_inputs_one: assert property (
        @(posedge clk) disable iff (reset || $initstate) (!$past(reset) && (X == 1'b1)) |-> ($past(A) && $past(B))
    );

    // If X is 0 now and not in reset prev cycle, then at least one of prev A or prev B was 0.
    x_zero_requires_prev_input_zero: assert property (
        @(posedge clk) disable iff (reset || $initstate) (!$past(reset) && (X == 1'b0)) |-> (!$past(A) || !$past(B))
    );

    // On falling edge of reset, X must be 0 in this cycle.
    x_zero_on_reset_fall: assert property (
        @(posedge clk) disable iff ($initstate) $fell(reset) |-> (X == 1'b0)
    );

endmodule

