module moore_fsm (
  input wire clk,
  input wire rst,
  input wire i_input,
  output reg o_output,
  output wire [2:0] o_current_state,
  output wire [2:0] o_next_state
);

  // Input value enumerations (constants)
  localparam  i_val_a = 1'b0;
  localparam  i_val_b = 1'b1;

  // State assignment (constants)
  localparam  STATE_U = 3'b000;
  localparam  STATE_V = 3'b001;
  localparam  STATE_W = 3'b010;
  localparam  STATE_X = 3'b011;
  localparam  STATE_Y = 3'b100;
  localparam  STATE_Z = 3'b101;

  reg [2:0] current_state;
  reg [2:0] next_state;

  always @ ( posedge clk, posedge rst ) begin
    if ( rst == 1'b1 ) begin
      current_state <= STATE_U;
    end else begin
      current_state <= next_state;
    end
  end

  assign o_current_state = current_state;
  assign o_next_state = next_state;

  always @ ( * ) begin
    case (current_state)
      STATE_U: begin
        if (i_input == i_val_a) begin
          next_state = STATE_Z;
        end else if (i_input == i_val_b) begin
          next_state = STATE_W;
        end
      end

      STATE_V: begin
        if (i_input == i_val_a) begin
          next_state = STATE_Z;
        end else if (i_input == i_val_b) begin
          next_state = STATE_W;
        end
      end

      STATE_W: begin
        if (i_input == i_val_a) begin
          next_state = STATE_X;
        end else if (i_input == i_val_b) begin
          next_state = STATE_U;
        end
      end

      STATE_X: begin
        if (i_input == i_val_a) begin
          next_state = STATE_Y;
        end else if (i_input == i_val_b) begin
          next_state = STATE_X;
        end
      end

      STATE_Y: begin
        if (i_input == i_val_a) begin
          next_state = STATE_V;
        end else if (i_input == i_val_b) begin
          next_state = STATE_Y;
        end
      end

      STATE_Z: begin
        if (i_input == i_val_a) begin
          next_state = STATE_Y;
        end else if (i_input == i_val_b) begin
          next_state = STATE_X;
        end
      end

      default: begin
        // unreachable states. go back to proper state
        next_state = STATE_U;
      end

    endcase
  end

  always @ ( * ) begin
    case (current_state)
      STATE_U:  begin
        o_output = 1'b1;
      end

      STATE_V:  begin
        o_output = 1'b0;
      end

      STATE_W:  begin
        o_output = 1'b0;
      end

      STATE_X:  begin
        o_output = 1'b0;
      end

      STATE_Y:  begin
        o_output = 1'b1;
      end

      STATE_Z:  begin
        o_output = 1'b1;
      end

      default:   begin
        // unreachable states
        o_output = 1'b0;
      end
    endcase
  end
endmodule

sva_code:
module moore_fsm_sva (
  input logic clk,
  input logic rst,
  input logic i_input,
  input logic o_output,
  input logic [2:0] o_current_state,
  input logic [2:0] o_next_state
);
  // Local copies of DUT constants for readability
  localparam logic [2:0] STATE_U = 3'b000;
  localparam logic [2:0] STATE_V = 3'b001;
  localparam logic [2:0] STATE_W = 3'b010;
  localparam logic [2:0] STATE_X = 3'b011;
  localparam logic [2:0] STATE_Y = 3'b100;
  localparam logic [2:0] STATE_Z = 3'b101;

  ///// State register behavior /////
  // On non-reset cycles (following a non-reset cycle), current_state updates from prior next_state.
  check_state_updates_from_next: assert property (
    @(posedge clk) disable iff (rst) $past(!rst) |-> (o_current_state == $past(o_next_state))
  );

  ///// Next-state combinational mapping /////
  // For STATE_U: 0->Z, 1->W.
  map_next_from_U: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_U) |-> (o_next_state == (i_input ? STATE_W : STATE_Z))
  );
  // For STATE_V: 0->Z, 1->W.
  map_next_from_V: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_V) |-> (o_next_state == (i_input ? STATE_W : STATE_Z))
  );
  // For STATE_W: 0->X, 1->U.
  map_next_from_W: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_W) |-> (o_next_state == (i_input ? STATE_U : STATE_X))
  );
  // For STATE_X: 0->Y, 1->X (self-loop on 1).
  map_next_from_X: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_X) |-> (o_next_state == (i_input ? STATE_X : STATE_Y))
  );
  // For STATE_Y: 0->V, 1->Y (self-loop on 1).
  map_next_from_Y: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_Y) |-> (o_next_state == (i_input ? STATE_Y : STATE_V))
  );
  // For STATE_Z: 0->Y, 1->X.
  map_next_from_Z: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_Z) |-> (o_next_state == (i_input ? STATE_X : STATE_Y))
  );
  // For invalid states (110/111): default goes to STATE_U.
  map_next_from_invalid_to_U: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {3'b110,3'b111}) |-> (o_next_state == STATE_U)
  );
  // next_state is always one of the defined encodings.
  check_next_state_legal: assert property (
    @(posedge clk) disable iff (rst) (o_next_state inside {STATE_U,STATE_V,STATE_W,STATE_X,STATE_Y,STATE_Z})
  );

  ///// Moore output mapping /////
  // For U/Y/Z, output must be 1.
  check_output_high_states: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {STATE_U,STATE_Y,STATE_Z}) |-> (o_output == 1'b1)
  );
  // For V/W/X, output must be 0.
  check_output_low_states: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {STATE_V,STATE_W,STATE_X}) |-> (o_output == 1'b0)
  );

  ///// Reset behavior /////
  // After a rising reset, current_state must be STATE_U by the next clock edge.
  reset_sets_state_U_next_cycle: assert property (
    @(posedge clk) $rose(rst) |-> ##1 (o_current_state == STATE_U)
  );

endmodule

module Vector_sva (
    input logic clk,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic [1:0] c
);
    ///// Functional correctness /////
    // Output equals bitwise AND of inputs.
    check_and_functionality: assert property (
        @(posedge clk) c === (a & b)
    );
    // Commutativity of AND reflected at output.
    check_commutativity: assert property (
        @(posedge clk) c === (b & a)
    );

    ///// Bit-level correctness /////
    // Bit 0 equals a[0] AND b[0].
    check_bit0: assert property (
        @(posedge clk) c[0] === (a[0] & b[0])
    );
    // Bit 1 equals a[1] AND b[1].
    check_bit1: assert property (
        @(posedge clk) c[1] === (a[1] & b[1])
    );

    ///// Identity and annihilator properties /////
    // When a is all ones, c mirrors b.
    check_identity_a_all_ones: assert property (
        @(posedge clk) (a == 2'b11) |-> (c === b)
    );
    // When b is all ones, c mirrors a.
    check_identity_b_all_ones: assert property (
        @(posedge clk) (b == 2'b11) |-> (c === a)
    );
    // When a is all zeros, c is zero.
    check_annihilator_a_all_zeros: assert property (
        @(posedge clk) (a == 2'b00) |-> (c === 2'b00)
    );
    // When b is all zeros, c is zero.
    check_annihilator_b_all_zeros: assert property (
        @(posedge clk) (b == 2'b00) |-> (c === 2'b00)
    );

    ///// Subset properties /////
    // Output ones are a subset of a's ones.
    check_output_subset_of_a: assert property (
        @(posedge clk) ((c & ~a) === 2'b00)
    );
    // Output ones are a subset of b's ones.
    check_output_subset_of_b: assert property (
        @(posedge clk) ((c & ~b) === 2'b00)
    );
endmodule

