module myDFF (CK, D, RN, SN, Q, QN);
input  CK ;
input  D ;
input  RN ;
input  SN ;
output Q ;
output QN ;
reg Q;

always @ (posedge CK) begin
    if (RN) begin
        Q <= 1'b0;
    end else if (SN) begin
        Q <= 1'b1;
    end else begin
        Q <= D;
    end
end

assign QN = ~Q;

endmodule

sva_code:
module myDFF_sva (
    input logic CK,
    input logic D,
    input logic RN,   // Active-HIGH synchronous reset
    input logic SN,   // Active-HIGH synchronous set
    input logic Q,
    input logic QN
);

    ///// Synchronous control behavior /////
    // When RN is asserted at a clock edge, Q must be 0 on the next cycle.
    check_sync_reset_drives_q0: assert property (
        @(posedge CK) RN |=> (Q == 1'b0)
    );

    // When SN is asserted (and RN is not), Q must be 1 on the next cycle.
    check_sync_set_drives_q1: assert property (
        @(posedge CK) disable iff (RN) SN |=> (Q == 1'b1)
    );

    // When neither RN nor SN is asserted, Q captures D on the next cycle.
    check_data_capture_when_no_ctrl: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (Q == $past(D))
    );

    // RN has priority over SN when both are asserted; Q must be 0 next cycle.
    check_reset_priority_over_set: assert property (
        @(posedge CK) (RN && SN) |=> (Q == 1'b0)
    );

    ///// Complementary output /////
    // QN is always the bitwise complement of Q.
    check_qn_complements_q: assert property (
        @(posedge CK) (QN == ~Q)
    );

    // When neither RN nor SN is asserted, QN next equals inversion of current D.
    check_qn_reflects_d_on_data_capture: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (QN == ~$past(D))
    );

    // When SN is asserted (and RN is not), QN must be 0 on the next cycle.
    check_qn_zero_on_set: assert property (
        @(posedge CK) disable iff (RN) SN |=> (QN == 1'b0)
    );

    // When RN is asserted, QN must be 1 on the next cycle.
    check_qn_one_on_reset: assert property (
        @(posedge CK) RN |=> (QN == 1'b1)
    );

endmodule

verilog_code:
module tone_generator (
  input clk,
  input rst,
  input [1:0] tone,
  output audio_out
);

parameter f_clk = 50_000_000; // frequency of the clock signal
parameter f_tone = 440; // frequency of the selected tone (default: A4)
parameter t_duration = 1; // duration of the tone in seconds (default: 1 second)

reg [31:0] tone_counter = 0;
reg [31:0] tone_duration = 0;
reg [31:0] sample_counter = 0;
reg [31:0] sample_period = 0;
reg [1:0] tone_type = 2'b00; // default: sine wave

wire tone_signal;

// DTMF tone generation
always @ (posedge clk) begin
  if (rst) begin
    tone_counter <= 0;
    tone_duration <= 0;
    sample_counter <= 0;
    sample_period <= 0;
    tone_type <= 2'b00;
  end else begin
    // Check if tone is selected
    if (tone != 2'b00) begin
      // A new tone is selected
      if (tone != tone_type) begin
        tone_counter <= 0;
        tone_duration <= t_duration * f_clk;
        sample_counter <= 0;
        sample_period <= f_clk / f_tone;
        tone_type <= tone;
      end else begin // Same tone is selected
        // Check if tone duration is reached
        if (tone_counter >= tone_duration) begin
          tone_counter <= 0;
          tone_duration <= 0;
          sample_counter <= 0;
          sample_period <= 0;
          tone_type <= 2'b00;
        end else begin
          tone_counter <= tone_counter + 1;
          sample_counter <= sample_counter + 1;
          // Check if a new sample is needed
          if (sample_counter >= sample_period) begin
            sample_counter <= 0;
          end
        end
      end
    end else begin // No tone is selected
      tone_counter <= 0;
      tone_duration <= 0;
      sample_counter <= 0;
      sample_period <= 0;
      tone_type <= 2'b00;
    end
  end
end

// Sine wave generation
assign tone_signal = (tone_counter >= (f_clk / (2 * f_tone))) ? 1'b1 : 1'b0;

// Audio output
assign audio_out = tone_signal;

endmodule

sva_code:
module tone_generator_sva #(
    parameter int unsigned f_clk = 50_000_000,
    parameter int unsigned f_tone = 440,
    parameter int unsigned t_duration = 1
) (
    input  logic        clk,
    input  logic        rst,
    input  logic [1:0]  tone,
    input  logic        audio_out,

    // Internal DUT signals
    input  logic [31:0] tone_counter,
    input  logic [31:0] tone_duration,
    input  logic [31:0] sample_counter,
    input  logic [31:0] sample_period,
    input  logic [1:0]  tone_type
);
    localparam int unsigned HALF_PERIOD    = f_clk / (2 * f_tone);
    localparam int unsigned DURATION_TICKS = t_duration * f_clk;

    ///// Reset behavior /////
    // Synchronous active-HIGH reset clears all internal state.
    reset_clears_state: assert property (
        @(posedge clk) rst |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                           (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                           (tone_type == 2'b00)
    );
    // During reset, audio_out is LOW (tone_counter is 0 and threshold > 0).
    reset_audio_low: assert property (
        @(posedge clk) rst |-> (audio_out == 1'b0)
    );

    ///// Idle behavior (no tone selected) /////
    // When tone==00, all counters/periods clear and no tone is latched.
    idle_clears_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone == 2'b00) |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                               (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                               (tone_type == 2'b00)
    );
    // When tone==00, audio_out is LOW.
    idle_audio_low: assert property (
        @(posedge clk) disable iff (rst)
            (tone == 2'b00) |-> (audio_out == 1'b0)
    );

    ///// New tone selection /////
    // On new non-zero tone selection, initialize duration/period and clear counters.
    new_tone_initializes_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone != $past(tone_type))
            |-> (tone_counter == 32'd0) && (sample_counter == 32'd0) &&
                (tone_duration == DURATION_TICKS) && (sample_period == (f_clk / f_tone)) &&
                (tone_type == tone)
    );

    ///// Active tone behavior /////
    // When current tone duration reached, clear state and deselect tone.
    end_of_tone_clears_state: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) >= $past(tone_duration))
            |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                (tone_type == 2'b00)
    );
    // While active (same tone) and not finished, tone_counter increments by 1.
    active_increments_tone_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (tone_counter == $past(tone_counter) + 32'd1)
    );
    // sample_counter increments when below sample_period during active tone.
    active_increments_sample_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) &&
            ($past(tone_counter) < $past(tone_duration)) &&
            ($past(sample_counter) < $past(sample_period))
            |-> (sample_counter == $past(sample_counter) + 32'd1)
    );
    // sample_counter resets to 0 when it reaches/exceeds sample_period.
    active_resets_sample_counter: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) &&
            ($past(tone_counter) < $past(tone_duration)) &&
            ($past(sample_counter) >= $past(sample_period))
            |-> (sample_counter == 32'd0)
    );
    // sample_period and tone_duration hold constant while active.
    active_holds_period_and_duration: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (sample_period == $past(sample_period)) && (tone_duration == $past(tone_duration))
    );
    // tone_type holds and equals input while active.
    active_holds_tone_type: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (tone_type == $past(tone_type)) && (tone_type == tone)
    );
    // sample_counter never exceeds sample_period while active.
    active_sample_counter_bound: assert property (
        @(posedge clk) disable iff (rst)
            (tone != 2'b00) && (tone == $past(tone_type)) && ($past(tone_counter) < $past(tone_duration))
            |-> (sample_counter <= sample_period)
    );

    ///// Output mapping /////
    // audio_out equals (tone_counter >= f_clk/(2*f_tone)).
    audio_out_matches_comparator: assert property (
        @(posedge clk) disable iff (rst)
            audio_out == (tone_counter >= HALF_PERIOD)
    );

endmodule

module binary_counter_sva (
    input logic CLK,
    input logic RST,
    input logic [3:0] Q
);
    ///// Reset behavior /////
    // When RST is asserted, Q must be 0 on the next clock.
    reset_forces_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

    ///// Counting behavior (disabled during reset) /////
    // When not at max, Q increments by 1 on the next clock.
    count_increments_when_not_max: assert property (
        @(posedge CLK) disable iff (RST) (Q != 4'hF) |=> (Q == $past(Q) + 1'b1)
    );

    // When at max, Q wraps to 0 on the next clock.
    count_wraps_when_max: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

    // LSB toggles every cycle when not in reset.
    lsb_toggles_without_reset: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q[0] == ~$past(Q[0]))
    );
endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [2:0] count
);
    ///// Reset behavior /////
    // While rst is asserted low, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 3'd0)
    );

    // On the cycle rst rises, the sampled count is still zero.
    check_release_cycle_value_zero: assert property (
        @(posedge clk) $rose(rst) |-> (count == 3'd0)
    );

    // On the cycle rst falls, the sampled count is zero (asynchronous assert).
    check_async_assert_immediate_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 3'd0)
    );

    ///// Counting behavior (enabled when rst is high) /////
    // With rst high on consecutive cycles, count increments by 1 (mod 8).
    check_increment_by_one: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count == ($past(count) + 3'd1))
    );

    // Explicit wrap-around: 7 rolls over to 0 when rst stays high.
    check_wrap_from_7_to_0: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // LSB toggles every cycle when counting is enabled.
    check_lsb_toggles_while_counting: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count[0] == ~$past(count[0]))
    );

    // One cycle after reset release, if rst remains high, count must be 1.
    check_first_increment_after_release: assert property (
        @(posedge clk) $rose(rst) |-> ##1 (rst |-> (count == 3'd1))
    );

    // Over two enabled cycles, count increases by 2.
    check_two_cycle_delta_two: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst,2) && $past(rst,1)) |-> (count == ($past(count,2) + 3'd2))
    );
endmodule

