    check_posedge_a1_updates_y: assert property (
        @(posedge A1) ##0 (Y == (B1 | A2))
    );
    // On A1 falling edge, Y must equal B1 after delta.
    check_negedge_a1_updates_y: assert property (
        @(negedge A1) ##0 (Y == B1)
    );
