    );

    // On the first cycle after reset deasserts, next update from 0 follows normal rule.
    check_post_reset_first_update: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> ##1 (count == (($past(max_value) == 32'd1) ? 32'd0 : 32'd1))
