module sky130_fd_sc_hd__o2bb2ai_sva (
    input logic clk,
    input logic Y,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2
);
    ///// Combinational function checks /////
    // Y equals (A1_N & A2_N) | (~B1 & ~B2).
    check_truth_function_sop: assert property (
        @(posedge clk) Y == ((A1_N & A2_N) | (~B1 & ~B2))
    );

    // Y equals ~(~(A2_N & A1_N) & (B1 | B2)).
    check_truth_function_demorgan: assert property (
        @(posedge clk) Y == ~(~(A2_N & A1_N) & (B1 | B2))
    );

    ///// Input-driven behavior /////
    // When both B inputs are 0, Y must be 1.
    check_y_high_when_no_b: assert property (
        @(posedge clk) (B1 == 1'b0 && B2 == 1'b0) |-> (Y == 1'b1)
    );

    // When B1 is 1, Y equals A1_N & A2_N.
    check_y_eq_aand_when_b1_high: assert property (
        @(posedge clk) (B1 == 1'b1) |-> (Y == (A1_N & A2_N))
    );

    // When B2 is 1, Y equals A1_N & A2_N.
    check_y_eq_aand_when_b2_high: assert property (
        @(posedge clk) (B2 == 1'b1) |-> (Y == (A1_N & A2_N))
    );

    // If any B is 1 and A1_N is 0, Y must be 0.
    check_y_low_when_a1_low_and_any_b: assert property (
        @(posedge clk) ((B1 | B2) && (A1_N == 1'b0)) |-> (Y == 1'b0)
    );

    // If any B is 1 and A2_N is 0, Y must be 0.
    check_y_low_when_a2_low_and_any_b: assert property (
        @(posedge clk) ((B1 | B2) && (A2_N == 1'b0)) |-> (Y == 1'b0)
    );

    // If both A_N inputs are 1, Y must be 1.
    check_y_high_when_a_both_high: assert property (
        @(posedge clk) ((A1_N & A2_N) == 1'b1) |-> (Y == 1'b1)
    );

    // If Y is 0, then some B is 1 and not both A_N are 1.
    check_y_zero_implication: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((B1 | B2) && (~(A1_N & A2_N)))
    );
endmodule

module pg_to_PG_sva (
    input logic clk,
    input logic [15:0] p,
    input logic [15:0] g,
    input logic [3:0] bp,
    input logic [3:0] bg
);

    ///// Block-generate definitions /////
    // bg[0] equals g[3] | p[3]&g[2] | p[3]&p[2]&g[1] | p[3]&p[2]&p[1]&g[0]
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3]
                               | (p[3] & g[2])
                               | (p[3] & p[2] & g[1])
                               | (p[3] & p[2] & p[1] & g[0]) )
    );
    // bg[1] equals g[7] | p[7]&g[6] | p[7]&p[6]&g[5] | p[7]&p[6]&p[5]&g[4]
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7]
                               | (p[7] & g[6])
                               | (p[7] & p[6] & g[5])
                               | (p[7] & p[6] & p[5] & g[4]) )
    );
    // bg[2] equals g[11] | p[11]&g[10] | p[11]&p[10]&g[9] | p[11]&p[10]&p[9]&g[8]
    check_bg2_definition: assert property (
        @(posedge clk) bg[2] == ( g[11]
                               | (p[11] & g[10])
                               | (p[11] & p[10] & g[9])
                               | (p[11] & p[10] & p[9] & g[8]) )
    );
    // bg[3] equals g[15] | p[15]&g[14] | p[15]&p[14]&g[13] | p[15]&p[14]&p[13]&g[12]
    check_bg3_definition: assert property (
        @(posedge clk) bg[3] == ( g[15]
                               | (p[15] & g[14])
                               | (p[15] & p[14] & g[13])
                               | (p[15] & p[14] & p[13] & g[12]) )
    );

    ///// Block-propagate definitions /////
    // bp[0] equals p[3]&p[2]&p[1]&p[0]
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );
    // bp[1] equals p[7]&p[6]&p[5]&p[4]
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );
    // bp[2] equals p[11]&p[10]&p[9]&p[8]
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );
    // bp[3] equals p[15]&p[14]&p[13]&p[12]
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

    ///// Necessary conditions for block-generate /////
    // If bg[0] is 1, at least one g in [3:0] is 1.
    check_bg0_implies_some_g: assert property (
        @(posedge clk) bg[0] |-> (g[3] || g[2] || g[1] || g[0])
    );
    // If bg[1] is 1, at least one g in [7:4] is 1.
    check_bg1_implies_some_g: assert property (
        @(posedge clk) bg[1] |-> (g[7] || g[6] || g[5] || g[4])
    );
    // If bg[2] is 1, at least one g in [11:8] is 1.
    check_bg2_implies_some_g: assert property (
        @(posedge clk) bg[2] |-> (g[11] || g[10] || g[9] || g[8])
    );
    // If bg[3] is 1, at least one g in [15:12] is 1.
    check_bg3_implies_some_g: assert property (
        @(posedge clk) bg[3] |-> (g[15] || g[14] || g[13] || g[12])
    );

endmodule

module shift_reg_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic shift_left,
    input logic shift_right,
    input logic [15:0] data_in,
    input logic [15:0] data_out
);
    // Internal flag to ensure $past is valid one cycle after reset deasserts.
    logic past_valid;
    always @(posedge clk or posedge reset) begin
        if (reset) past_valid <= 1'b0;
        else       past_valid <= 1'b1;
    end

    // Load updates data_out with data_in on next cycle.
    check_load_updates_data_out: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load) |=> (data_out == $past(data_in))
    );

    // Load has priority over any shift signals.
    check_load_priority_over_shifts: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load && (shift_left || shift_right)) |=> (data_out == $past(data_in))
    );

    // Shift-left updates data_out with left-shifted previous value, LSB filled with 0.
    check_shift_left_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

    // Shift-left inserts 0 into bit 0.
    check_shift_left_inserts_zero_lsb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[0] == 1'b0)
    );

    // Shift-left moves bits [14:0] into [15:1].
    check_shift_left_moves_upper_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[15:1] == $past(data_out[14:0]))
    );

    // Shift-right updates data_out with right-shifted previous value, MSB filled with 0.
    check_shift_right_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out == { 1'b0, $past(data_out[15:1]) })
    );

    // Shift-right inserts 0 into bit 15.
    check_shift_right_inserts_zero_msb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[15] == 1'b0)
    );

    // Shift-right moves bits [15:1] into [14:0].
    check_shift_right_moves_lower_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[14:0] == $past(data_out[15:1]))
    );

    // When both shifts are asserted (no load), left shift takes priority.
    check_shift_conflict_left_wins: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left && shift_right) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

    // With no operation requested, data_out holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && !shift_right) |=> (data_out == $past(data_out))
    );
endmodule

