module bcd_to_7seg (
    input [3:0] BCD,
    output reg a, b, c, d, e, f, g
);

    always @(*) begin
        case (BCD)
            4'b0000: begin
                a = 1; b = 1; c = 1; d = 1; e = 1; f = 1; g = 0;
            end
            4'b0001: begin
                a = 0; b = 1; c = 1; d = 0; e = 0; f = 0; g = 0;
