module and4_module_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X
);
    // X equals the bitwise AND of A, B, C, and D.
    check_and_equation: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

    // X can be HIGH only if all inputs are HIGH.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

    // All inputs HIGH implies X is HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

    // A LOW forces X LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

    // B LOW forces X LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

    // C LOW forces X LOW.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

    // D LOW forces X LOW.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

    // X rising edge only when all inputs are HIGH.
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A && B && C && D)
    );

    // X falling edge implies at least one input is LOW.
    check_x_fall_requires_any_low: assert property (
        @(posedge clk) $fell(X) |-> (!A || !B || !C || !D)
    );
endmodule

module motor_controller_sva (
    input logic clk,
    input logic rst,
    input logic [7:0] speed,
    input logic [7:0] motor_speed
);
    ///// Reset behavior /////
    // During reset, motor_speed is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (motor_speed == 8'd0)
    );

    // While reset stays asserted across cycles, motor_speed remains zero.
    check_zero_while_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (motor_speed == 8'd0)
    );

    // On a falling edge of reset, output at this sample is zero (held from prior reset cycle).
    check_output_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(rst) |-> (motor_speed == 8'd0)
    );

    // On a rising edge of reset, async reset clears output to zero by this sample.
    check_output_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(rst) |-> (motor_speed == 8'd0)
    );

    ///// Functional behavior /////
    // When not in/reset for prior cycle, motor_speed equals previous cycle's speed.
    check_capture_prev_speed: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst)) |-> (motor_speed == $past(speed))
    );

    // If out of reset for two cycles and input unchanged between them, output is stable.
    check_output_stable_when_input_stable: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && !$past(rst,2) && ($past(speed) == $past(speed,2))) |-> (motor_speed == $past(motor_speed))
    );

    // If out of reset for two cycles and output changed, input must have changed in the prior cycle.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && !$past(rst,2) && (motor_speed != $past(motor_speed))) |-> ($past(speed) != $past(speed,2))
    );

    // If out of reset and motor_speed is zero, prior cycle's speed must have been zero.
    check_output_zero_means_prior_input_zero: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && (motor_speed == 8'd0)) |-> ($past(speed) == 8'd0)
    );
endmodule

module counter_4bit_sva (
  input logic clk,
  input logic reset,
  input logic enable,
  input logic [3:0] count
);
  // On reset HIGH, next cycle count is driven to 0.
  reset_clears_next: assert property (
    @(posedge clk) reset |=> (count == 4'd0)
  );

  // If reset stays HIGH across cycles, count is 0 on the later cycle.
  reset_holds_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 4'd0)
  );

  // On reset falling edge, count is 0 in that cycle (result of prior reset).
  count_zero_on_reset_fall: assert property (
    @(posedge clk) $fell(reset) |-> (count == 4'd0)
  );

  // With previous enable and no reset, count increments by 1 (mod 16).
  increment_on_prev_enable: assert property (
    @(posedge clk) disable iff (reset)
      ($past(enable) && !$past(reset)) |-> (count == $past(count) + 4'd1)
  );

  // With previous no enable and no reset, count holds its value.
  hold_on_prev_disable: assert property (
    @(posedge clk) disable iff (reset)
      (!$past(enable) && !$past(reset)) |-> (count == $past(count))
  );

  // Any change in count must be caused by previous reset or previous enable.
  change_requires_prev_control: assert property (
    @(posedge clk) $changed(count) |-> ($past(reset) || $past(enable))
  );

  // With previous enable and no reset, count must change.
  prev_enable_implies_change: assert property (
    @(posedge clk) disable iff (reset)
      ($past(enable) && !$past(reset)) |-> $changed(count)
  );

  // With previous enable at max value and no reset, wrap to 0 next cycle.
  wrap_on_max: assert property (
    @(posedge clk) disable iff (reset)
      ($past(enable) && !$past(reset) && ($past(count) == 4'hF)) |-> (count == 4'd0)
  );
endmodule

