    check_function_equivalence: assert property (
        @(posedge clk) X == (A | ~B_N)
    );

    // If A is 1, X must be 1.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

    // If B_N is 0, X must be 1.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (~B_N) |-> X
