module PicoBlaze_OutReg
	#(parameter LOCAL_PORT_ID = 8'h00)
	(
	clk,
	reset,
	port_id,
	write_strobe,
	out_port,
	new_out_port);
input  wire        clk;
input  wire        reset;
input  wire    	 [7:0] port_id;
input  wire        write_strobe;
input  wire        [7:0] out_port;
output reg  		 [7:0] new_out_port;
reg RegEnable=1;





always @ (*)
	begin
		if (write_strobe == 1)
			begin
				case (port_id)
					LOCAL_PORT_ID: RegEnable = 1;
					default: RegEnable = 0;
				endcase
			end
		else
			RegEnable=0;
	end



	always @ (posedge clk, posedge reset)
	begin
		if(reset == 1)
			new_out_port <= 8'h00;
		else
			begin
				if(RegEnable == 1)
					new_out_port <= out_port;
				else
					new_out_port <= new_out_port;
			end
	end

endmodule

sva_code:
module PicoBlaze_OutReg_sva #(
    parameter LOCAL_PORT_ID = 8'h00
) (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  port_id,
    input  logic        write_strobe,
    input  logic [7:0]  out_port,
    input  logic [7:0]  new_out_port,
    input  logic        RegEnable
);

    ///// Reset behavior /////
    // While reset is HIGH, new_out_port must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (new_out_port == 8'h00)
    );

    // On the cycle reset deasserts (HIGH->LOW), new_out_port remains 0.
    reset_fall_keeps_zero: assert property (
        @(posedge clk) $fell(reset) |-> (new_out_port == 8'h00)
    );

    ///// RegEnable decode /////
    // RegEnable equals write_strobe && (port_id == LOCAL_PORT_ID).
    regenable_definition: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable == (write_strobe && (port_id == LOCAL_PORT_ID))
    );

    // If RegEnable is HIGH, write_strobe must be HIGH.
    regenable_requires_strobe: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable |-> (write_strobe == 1'b1)
    );

    // If RegEnable is HIGH, port_id must match LOCAL_PORT_ID.
    regenable_requires_port_match: assert property (
        @(posedge clk) disable iff (reset)
            RegEnable |-> (port_id == LOCAL_PORT_ID)
    );

    ///// Register update semantics /////
    // A valid write updates new_out_port with out_port on the next clock.
    update_on_write_hit: assert property (
        @(posedge clk) disable iff (reset)
            (write_strobe && (port_id == LOCAL_PORT_ID)) |=> (new_out_port == $past(out_port))
    );

    // If there is no valid write in two consecutive cycles, new_out_port holds its value.
    hold_when_no_write_two_cycles: assert property (
        @(posedge clk) disable iff (reset)
            ( !(write_strobe && (port_id == LOCAL_PORT_ID))
              ##1 !(write_strobe && (port_id == LOCAL_PORT_ID)) )
            |-> (new_out_port == $past(new_out_port))
    );

endmodule

verilog_code:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] SUM,
    output reg OVERFLOW,
    output reg EQUAL,
    output reg GREATER_THAN,
    output reg LESS_THAN
);

    wire [3:0] add_sub_out;
    wire [1:0] comp_out;
    reg overflow_int;

    reg carry_in;

    adder_subtractor add_sub (
        .A(A),
        .B(B),
        .SUBTRACT(SUBTRACT),
        .OUT(add_sub_out),
        .OVERFLOW(overflow_int)
    );

    comparator_2bit comp (
        .A(A),
        .B(B),
        .OUT(comp_out)
    );

    always @* begin
        SUM <= add_sub_out;
        OVERFLOW <= overflow_int;
        EQUAL <= (comp_out == 2'b01);
        GREATER_THAN <= (comp_out == 2'b10);
        LESS_THAN <= (comp_out == 2'b00);
    end
endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] OUT,
    output reg OVERFLOW
);

    wire [3:0] twos_comp_B = (~B) + 1;

    always @* begin
        OUT <= A;
        OVERFLOW <= 0;
        if (SUBTRACT) begin
            OUT <= A + twos_comp_B;
        end else begin
            OUT <= A + B;
        end
        if (A >= OUT && SUBTRACT) begin
            OVERFLOW <= 1;
        end else if (A <= OUT && !SUBTRACT) begin
            OVERFLOW <= 1;
        end
    end
endmodule
module comparator_2bit (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

    always @(*) begin
        if (A > B) begin
            OUT <= 2'b10;
        end else if (A < B) begin
            OUT <= 2'b00;
        end else begin
            OUT <= 2'b01;
        end
    end
endmodule

