sva_code:
module my_4input_nand_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);
    // Y equals NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge A or posedge B or posedge C or posedge D) Y == ~(A & B & C & D)
    );

    // If any input is 0, Y must be 1.
    check_any_zero_implies_y1: assert property (
        @(posedge A or posedge B or posedge C or posedge D) ((A == 1'b0) || (B == 1'b0) || (C == 1'b0) || (D == 1'b0)) |-> (Y == 1'b1)
    );

    // If all inputs are 1, Y must be 0.
    check_all_ones_implies_y0: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (A && B && C && D) |-> (Y == 1'b0)
    );

    // If Y is 0, then all inputs must be 1.
    check_y0_implies_all_ones: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (Y == 1'b0) |-> (A && B && C && D)
    );

    // If Y is 1, then at least one input must be 0.
    check_y1_implies_any_zero: assert property (
        @(posedge A or posedge B or posedge C or posedge D) (Y == 1'b1) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0) || (D == 1'b0))
    );

    // De Morgan equivalence: Y equals (!A || !B || !C || !D).
    check_demorgan_form: assert property (
        @(posedge A or posedge B or posedge C or posedge D) Y == (!A || !B || !C || !D)
    );

    // On A rising when others are 1, Y must be 0.
    check_posedge_a_all_ones_y0: assert property (
        @(posedge A) (B && C && D) |-> (Y == 1'b0)
    );

    // On B rising when others are 1, Y must be 0.
    check_posedge_b_all_ones_y0: assert property (
        @(posedge B) (A && C && D) |-> (Y == 1'b0)
    );

    // On C rising when others are 1, Y must be 0.
    check_posedge_c_all_ones_y0: assert property (
        @(posedge C) (A && B && D) |-> (Y == 1'b0)
    );

    // On D rising when others are 1, Y must be 0.
    check_posedge_d_all_ones_y0: assert property (
        @(posedge D) (A && B && C) |-> (Y == 1'b0)
    );
endmodule

verilog_code:
module gray_code_converter (
    input [3:0] binary_in,
    input select,
    output reg [3:0] gray_out
);

    always @ (select or binary_in) begin
        if (select == 1'b1) begin
            gray_out[0] <= binary_in[0];
            gray_out[1] <= binary_in[0] ^ binary_in[1];
            gray_out[2] <= binary_in[1] ^ binary_in[2];
            gray_out[3] <= binary_in[2] ^ binary_in[3];
        end else begin
            gray_out <= binary_in;
        end
    end

endmodule

sva_code:
module gray_code_converter_sva (
    input  logic clk,              // sampling clock for assertions
    input  logic [3:0] binary_in,
    input  logic select,
    input  logic [3:0] gray_out
);
    // LSB always matches binary_in[0].
    check_lsb_matches: assert property (
        @(posedge clk) (gray_out[0] == binary_in[0])
    );

    // When select=0, output passes through binary_in.
    check_passthrough_when_select0: assert property (
        @(posedge clk) (!select) |-> (gray_out == binary_in)
    );

    // When select=1, gray_out[1] is binary_in[0] XOR binary_in[1].
    check_gray_bit1_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[1] == (binary_in[0] ^ binary_in[1]))
    );

    // When select=1, gray_out[2] is binary_in[1] XOR binary_in[2].
    check_gray_bit2_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[2] == (binary_in[1] ^ binary_in[2]))
    );

    // When select=1, gray_out[3] is binary_in[2] XOR binary_in[3].
    check_gray_bit3_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out[3] == (binary_in[2] ^ binary_in[3]))
    );

    // When select=1, full vector matches Gray-code mapping.
    check_full_gray_mapping_when_select1: assert property (
        @(posedge clk) (select) |-> (gray_out == { (binary_in[2] ^ binary_in[3]),
                                                   (binary_in[1] ^ binary_in[2]),
                                                   (binary_in[0] ^ binary_in[1]),
                                                   (binary_in[0]) })
    );

    // If inputs are stable across cycles, output remains stable.
    check_stability_with_stable_inputs: assert property (
        @(posedge clk) ($stable(binary_in) && $stable(select)) |-> $stable(gray_out)
    );
endmodule

verilog_code:
module counter (
    input clk,
    input reset,
    input [31:0] max_count,
    output reg [31:0] count
);

always @(posedge clk) begin
    if (reset) begin
        count <= 0;
    end else if (count == max_count) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva_code:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic [31:0] max_count,
    input logic [31:0] count
);

    // Synchronous reset drives count to 0 on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

    // If reset is held across consecutive cycles, count is 0 on the later cycle.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 32'd0)
    );

    // On reset deassertion (prior cycle asserted, now deasserted), count is 0.
    reset_release_zero: assert property (
        @(posedge clk) ($past(reset) && !reset) |-> (count == 32'd0)
    );

    // When not in reset: if prior count == prior max_count, next count is 0 (wrap).
    wrap_on_match_prev: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) == $past(max_count)) |-> (count == 32'd0)
    );

    // When not in reset: if prior count != prior max_count, next count increments by 1.
    increment_on_neq_prev: assert property (
        @(posedge clk) disable iff (reset)
            ($past(count) != $past(max_count)) |-> (count == ($past(count) + 32'd1))
    );

    // When not in reset: next count matches the RTL branching (wrap or increment).
    next_value_follows_rtl: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset)) |-> (count == (($past(count) == $past(max_count)) ? 32'd0 : ($past(count) + 32'd1)))
    );

endmodule

