module rippleCounter_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] out
);

    ///// Reset behavior /////
    // While reset is asserted, out is 0 at each clock.
    check_reset_zero: assert property (
        @(posedge clk) (!rst_n |-> (out == 4'd0))
    );

    ///// Counting behavior /////
    // When running and previous out != 15, out increments by 1.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && ($past(out) != 4'd15)) |-> (out == $past(out) + 4'd1)
    );

    // When running and previous out == 15, out wraps to 0.
    check_wrap_15_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && ($past(out) == 4'd15)) |-> (out == 4'd0)
    );

    // When running, out changes every cycle (no hold).
    check_out_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (out != $past(out))
    );

    // When out of reset for 16 consecutive cycles, state repeats every 16.
    check_periodicity_16: assert property (
        @(posedge clk) disable iff (!rst_n)
            ( rst_n && $past(rst_n,1) && $past(rst_n,2) && $past(rst_n,3) && $past(rst_n,4)
              && $past(rst_n,5) && $past(rst_n,6) && $past(rst_n,7) && $past(rst_n,8)
              && $past(rst_n,9) && $past(rst_n,10) && $past(rst_n,11) && $past(rst_n,12)
              && $past(rst_n,13) && $past(rst_n,14) && $past(rst_n,15) ) |-> (out == $past(out,16))
    );

    ///// Reset edge effects /////
    // One cycle after a reset assertion, out is 0.
    check_zero_next_after_reset_assert: assert property (
        @(posedge clk) $fell(rst_n) |=> (out == 4'd0)
    );

    // On the clock where reset deasserts, out is still 0.
    check_zero_at_reset_release_edge: assert property (
        @(posedge clk) disable iff (!rst_n)
            $rose(rst_n) |-> (out == 4'd0)
    );

    // One cycle after reset deasserts, out becomes 1.
    check_one_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n)
            $rose(rst_n) |=> (out == 4'd1)
    );

    ///// Additional invariants /////
    // When running, out == 0 only if previous out was 15.
    check_zero_only_after_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && (out == 4'd0)) |-> ($past(out) == 4'd15)
    );

    // When running, LSB toggles every cycle.
    check_lsb_toggles: assert property (
        @(posedge clk) disable iff (!rst_n)
            $past(rst_n) |-> (out[0] == ~$past(out[0]))
    );

endmodule

verilog_code:
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output [7:0] q,
    output [7:0] anyedge_or_d
);

    // Define internal wires and signals
    wire [7:0] q_ff;
    wire [7:0] q_t;
    wire [7:0] anyedge;
    wire [7:0] or_result;

    // Instantiate the D flip-flop module
    dff_module dff_inst (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q_ff)
    );

    // Instantiate the any edge detection module
    anyedge_module anyedge_inst (
        .clk(clk),
        .reset(reset),
        .d(q_ff),
        .q(anyedge)
    );

    // Implement the T flip-flops for the D flip-flop module
    assign q_t[0] = q_ff[0] ^ d[0];
    assign q_t[1] = q_ff[1] ^ d[1];
    assign q_t[2] = q_ff[2] ^ d[2];
    assign q_t[3] = q_ff[3] ^ d[3];
    assign q_t[4] = q_ff[4] ^ d[4];
    assign q_t[5] = q_ff[5] ^ d[5];
    assign q_t[6] = q_ff[6] ^ d[6];
    assign q_t[7] = q_ff[7] ^ d[7];

    // Instantiate the OR gate module
    or_gate_module or_gate_inst (
        .a(q_t),
        .b(anyedge),
        .c(or_result)
    );

    // Assign the output signals
    assign q = q_ff;
    assign anyedge_or_d = or_result;

endmodule

// Define the D flip-flop module
module dff_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    always @(negedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= d;
        end
    end

endmodule

// Define the any edge detection module
module anyedge_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d,
    output reg [7:0] q
);

    reg [7:0] d_ff;

    always @(posedge clk) begin
        if (reset) begin
            d_ff <= 8'b0;
            q <= 8'b0;
        end else begin
            d_ff <= d;
            q <= d ^ d_ff;
        end
    end

endmodule

// Define the OR gate module
module or_gate_module (
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] c
);

    always @(a or b) begin
        c <= a | b;
    end

endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic reset,      // Synchronous active-high reset
    input logic [7:0] d,
    input logic [7:0] q,
    input logic [7:0] anyedge_or_d
);

    ///// dff_module (negedge clock) /////
    // When not in reset now and previously, q equals prior-cycle d at each negedge.
    dff_loads_d_on_negedge: assert property (
        @(negedge clk) disable iff (reset) (!$past(reset)) |-> (q == $past(d))
    );

    // If reset was asserted on the previous negedge, q must now be 0.
    dff_prev_reset_drives_zero: assert property (
        @(negedge clk) $past(reset) |-> (q == 8'h00)
    );

    // If reset is asserted on this negedge, q will be 0 by the next negedge.
    dff_reset_now_zero_next: assert property (
        @(negedge clk) reset |=> (q == 8'h00)
    );

    ///// anyedge_module + or_gate_module observed at posedge /////
    // OR output equals (q ^ d) OR (q toggled between the last two posedges).
    or_exact_decomposition: assert property (
        @(posedge clk) disable iff (reset) anyedge_or_d == ((q ^ d) | ($past(q) ^ $past(q,2)))
    );

    // OR output must include all 1s from (q ^ d).
    or_includes_q_xor_d: assert property (
        @(posedge clk) disable iff (reset) (((q ^ d) & ~anyedge_or_d) == 8'h00)
    );

    // OR output must include bits that toggled in q between the last two posedges.
    or_includes_prev_q_toggle: assert property (
        @(posedge clk) disable iff (reset) ((($past(q) ^ $past(q,2)) & ~anyedge_or_d) == 8'h00)
    );

    // If (q ^ d) is zero, OR output equals the previous-cycle anyedge term.
    or_reduces_to_prev_anyedge_when_qeqd: assert property (
        @(posedge clk) disable iff (reset) ((q ^ d) == 8'h00) |-> (anyedge_or_d == ($past(q) ^ $past(q,2)))
    );

    // If neither source contributes (q==d and no prior q toggle), OR output is zero.
    or_zero_when_no_sources: assert property (
        @(posedge clk) disable iff (reset) ((q == d) && ($past(q) == $past(q,2))) |-> (anyedge_or_d == 8'h00)
    );

    // After a posedge with reset asserted, next posedge OR output equals (q ^ d) (anyedge term cleared).
    or_after_reset_reduces_to_q_xor_d: assert property (
        @(posedge clk) reset |=> (anyedge_or_d == (q ^ d))
    );

endmodule

module and3b_sva (
    input logic A_N,
    input logic B,
    input logic C,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);
    // Note: Combinational DUT with no clock/reset; sample on any edge of A_N/B/C.

    // X is 1 when A_N, B, and C are all 1.
    check_all_ones_gives_one: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (A_N === 1'b1 && B === 1'b1 && C === 1'b1) |=> (X === 1'b1)
    );

    // A_N at 0 forces X to 0.
    check_a0_forces_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (A_N === 1'b0) |=> (X === 1'b0)
    );

    // B at 0 forces X to 0.
    check_b0_forces_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (B === 1'b0) |=> (X === 1'b0)
    );

    // C at 0 forces X to 0.
    check_c0_forces_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (C === 1'b0) |=> (X === 1'b0)
    );

    // If X is 1, then A_N, B, and C must all be 1.
    check_x1_implies_all_ones: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (X === 1'b1) |=> (A_N === 1'b1 && B === 1'b1 && C === 1'b1)
    );

    // If X is 0, then at least one input is 0.
    check_x0_implies_some_zero: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (X === 1'b0) |=> ((A_N === 1'b0) || (B === 1'b0) || (C === 1'b0))
    );

    // If some input is X/Z, and no input is 0, and not all are 1, then X is unknown.
    check_someX_no_zero_not_all1_implies_xX: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            ($isunknown({A_N,B,C}) &&
             !((A_N === 1'b0) || (B === 1'b0) || (C === 1'b0)) &&
             !((A_N === 1'b1) && (B === 1'b1) && (C === 1'b1))) |=> $isunknown(X)
    );

    // If X is unknown, then some input is X/Z, no input is 0, and not all are 1.
    check_xX_implies_someX_no_zero_not_all1: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            $isunknown(X) |=> ($isunknown({A_N,B,C}) &&
                               !((A_N === 1'b0) || (B === 1'b0) || (C === 1'b0)) &&
                               !((A_N === 1'b1) && (B === 1'b1) && (C === 1'b1)))
    );

    // When all inputs are known (0/1), X is not unknown.
    check_no_x_when_inputs_known: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (!$isunknown({A_N,B,C})) |=> (!$isunknown(X))
    );

    // If A_N is X/Z and B,C are 1, X is unknown.
    check_ax_bc1_implies_xX: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (($isunknown(A_N)) && (B === 1'b1) && (C === 1'b1)) |=> $isunknown(X)
    );

    // If B is X/Z and A_N,C are 1, X is unknown.
    check_bx_ac1_implies_xX: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (($isunknown(B)) && (A_N === 1'b1) && (C === 1'b1)) |=> $isunknown(X)
    );

    // If C is X/Z and A_N,B are 1, X is unknown.
    check_cx_ab1_implies_xX: assert property (
        @(posedge A_N or negedge A_N or posedge B or negedge B or posedge C or negedge C)
            (($isunknown(C)) && (A_N === 1'b1) && (B === 1'b1)) |=> $isunknown(X)
    );

