verilog_code:
module top_module (
    input clk,
    input reset,
    input up_down,
    input [7:0] in_hi,
    input [7:0] in_lo,
    output [15:0] out
);

wire [2:0] count;
wire [15:0] hw;
wire [15:0] final_out;

// Instantiate the 3-bit binary counter module
counter_3bit counter_inst (
    .clk(clk),
    .reset(reset),
    .up_down(up_down),
    .count(count)
);

// Instantiate the combinational circuit module
combinational_circuit comb_inst (
    .in_hi(in_hi),
    .in_lo(in_lo),
    .out(hw)
);

// Instantiate the functional module
functional_module func_inst (
    .hw(hw),
    .count(count),
    .out(final_out)
);

// Assign the final output to the output port
assign out = final_out;

endmodule

module counter_3bit (
    input clk,
    input reset,
    input up_down,
    output reg [2:0] count
);

always @(posedge clk) begin
    if (reset == 0) begin
        count <= 3'b000;
    end else if (up_down == 1) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

module combinational_circuit (
    input [7:0] in_hi,
    input [7:0] in_lo,
    output reg [15:0] out
);

always @* begin
    out = {in_hi, in_lo};
end

endmodule

module functional_module (
    input [15:0] hw,
    input [2:0] count,
    output reg [15:0] out
);

always @(*) begin
    out = hw + count;
end

endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic up_down,
    input logic [7:0] in_hi,
    input logic [7:0] in_lo,
    input logic [15:0] out
);
    ///// Reset behavior /////
    // On synchronous active-low reset, out equals {in_hi,in_lo}.
    check_reset_out_base: assert property (
        @(posedge clk) (reset == 1'b0) |-> (out == {in_hi, in_lo})
    );

    ///// Functional invariants /////
    // Out minus base is always in [0..7] when not in reset.
    check_delta_range: assert property (
        @(posedge clk) disable iff (!reset) ((out - {in_hi, in_lo}) <= 16'd7)
    );

    // When counting up, next delta = (prev delta + 1) mod 8.
    check_delta_inc_mod8: assert property (
        @(posedge clk) disable iff (!reset)
            (up_down == 1'b1) |=> ((out - {in_hi, in_lo}) == ((($past(out) - $past({in_hi, in_lo})) + 16'd1) & 16'h0007))
    );

    // When counting down, next delta = (prev delta - 1) mod 8.
    check_delta_dec_mod8: assert property (
        @(posedge clk) disable iff (!reset)
            (up_down == 1'b0) |=> ((out - {in_hi, in_lo}) == ((($past(out) - $past({in_hi, in_lo})) + 16'd7) & 16'h0007))
    );

    // Delta (out-base) changes every cycle when not in reset.
    check_delta_changes_every_cycle: assert property (
        @(posedge clk) disable iff (!reset)
            1'b1 |=> ((out - {in_hi, in_lo}) != ($past(out) - $past({in_hi, in_lo})))
    );

    ///// Boundary wrap cases /////
    // If delta is 7 and counting up, next delta becomes 0.
    check_inc_wrap_7_to_0: assert property (
        @(posedge clk) disable iff (!reset)
            (((out - {in_hi, in_lo}) == 16'd7) && (up_down == 1'b1)) |=> ((out - {in_hi, in_lo}) == 16'd0)
    );

    // If delta is 0 and counting down, next delta becomes 7.
    check_dec_wrap_0_to_7: assert property (
        @(posedge clk) disable iff (!reset)
            (((out - {in_hi, in_lo}) == 16'd0) && (up_down == 1'b0)) |=> ((out - {in_hi, in_lo}) == 16'd7)
    );

    // If delta != 7 and counting up, next delta increments by 1.
    check_inc_no_wrap_plus1: assert property (
        @(posedge clk) disable iff (!reset)
            (((out - {in_hi, in_lo}) != 16'd7) && (up_down == 1'b1)) |=> ((out - {in_hi, in_lo}) == (($past(out) - $past({in_hi, in_lo})) + 16'd1))
    );

    // If delta != 0 and counting down, next delta decrements by 1.
    check_dec_no_wrap_minus1: assert property (
        @(posedge clk) disable iff (!reset)
            (((out - {in_hi, in_lo}) != 16'd0) && (up_down == 1'b0)) |=> ((out - {in_hi, in_lo}) == (($past(out) - $past({in_hi, in_lo})) - 16'd1))
    );

    ///// Post-reset first-cycle behavior /////
    // Immediately after reset release, if up, delta becomes 1.
    check_post_reset_release_inc: assert property (
        @(posedge clk) ($past(reset) == 1'b0 && reset == 1'b1 && up_down == 1'b1) |-> ((out - {in_hi, in_lo}) == 16'd1)
    );

    // Immediately after reset release, if down, delta becomes 7.
    check_post_reset_release_dec: assert property (
        @(posedge clk) ($past(reset) == 1'b0 && reset == 1'b1 && up_down == 1'b0) |-> ((out - {in_hi, in_lo}) == 16'd7)
    );
endmodule

verilog_code:
module shift_register (
    input CLK,
    input LOAD,
    input SHIFT,
    input [7:0] DATA_IN,
    output [7:0] Q_OUT,
    output [7:0] Q_BAR_OUT
);

reg [7:0] shift_reg;

always @(posedge CLK) begin
    if (LOAD) begin
        shift_reg <= DATA_IN;
    end
    else if (SHIFT) begin
        shift_reg <= {shift_reg[6:0], DATA_IN[0]};
    end
end

assign Q_OUT = shift_reg;
assign Q_BAR_OUT = ~shift_reg;

endmodule

sva_code:
module shift_register_sva (
    input logic CLK,
    input logic LOAD,
    input logic SHIFT,
    input logic [7:0] DATA_IN,
    input logic [7:0] Q_OUT,
    input logic [7:0] Q_BAR_OUT
);
    ///// Output complement relationship /////
    // Q_BAR_OUT is always bitwise inverse of Q_OUT.
    check_qbar_is_invert: assert property (
        @(posedge CLK) (Q_BAR_OUT == ~Q_OUT)
    );

    ///// LOAD behavior /////
    // On LOAD, next Q_OUT equals current DATA_IN (LOAD has priority over SHIFT).
    check_load_updates_qout: assert property (
        @(posedge CLK) LOAD |-> (Q_OUT == $past(DATA_IN))
    );

    ///// SHIFT behavior /////
    // On SHIFT without LOAD, next Q_OUT is left-shifted with DATA_IN[0] into bit 0.
    check_shift_updates_qout: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> (Q_OUT == { $past(Q_OUT[6:0]), $past(DATA_IN[0]) })
    );

    // On SHIFT without LOAD, next LSB comes from DATA_IN[0].
    check_shift_lsb_from_datain0: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> (Q_OUT[0] == $past(DATA_IN[0]))
    );

    // On SHIFT without LOAD, upper bits move down by one.
    check_shift_upper_bits_move_down: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |-> (Q_OUT[7:1] == $past(Q_OUT[6:0]))
    );

    ///// Hold behavior /////
    // With neither LOAD nor SHIFT, Q_OUT holds its value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !SHIFT) |-> (Q_OUT == $past(Q_OUT))
    );

    ///// Change causality /////
    // Any change in Q_OUT must be caused by a LOAD or SHIFT in the prior cycle.
    check_change_requires_load_or_shift: assert property (
        @(posedge CLK) ($past(1'b1) && $changed(Q_OUT)) |=> $past(LOAD || SHIFT)
    );
endmodule

