    // On negedge of a, out must equal b (since a==0).
    check_out_eq_b_on_negedge_a: assert property (
        @(negedge a) (out_wire == b)
    );

    // On posedge of b, out must equal ~a (since b==1).
    check_out_eq_nota_on_posedge_b: assert property (
