    check_out_overall_function: assert property (
        @(posedge a or posedge b or posedge c or posedge sel_2to1 or posedge sel_3to1 or posedge out)
        out == (sel_3to1 ? (sel_2to1 ? ~a : ~b) : ~c)
    );

