    );

parameter        SecondCount    =    8001800;          reg    [23:0]    counter        =    0;                reg    [23:0]    freq           =    0;                reg    [23:0]    secondcounter  =    0;                reg              stopin         =    0;                reg              inreseted      =    0;                always @(posedge clk)    
begin
        if(secondcounter == SecondCount)
        begin
            secondcounter     <= 0;
            stopin             <= 1;
            freq                 <=    counter*2;
        end
        else 
            if(~stopin)
                secondcounter <= secondcounter + 1;

        if(inreseted)
            stopin <= 0;
end

always @(negedge freqin)
begin
        if(~stopin)
        begin
            counter    <=    counter + 1;
            inreseted <= 0;
        end
        else
        begin
            counter <= 0;
            inreseted <= 1;
        end
end

assign frequency = freq;

endmodule

