    check_c1_low_forces_x0: assert property (
        @(posedge clk) disable iff (1'b0) (!C1) |-> (!X)
    );

    // All A inputs low force X low.
    check_all_a_low_forces_x0: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !A2 && !A3) |-> (!X)
    );

