    @(posedge clk) disable iff (1'b0) $isunknown(sel) |-> (out == 4'b0000)
  );

  // For known sel, out equals the selected input.
  check_mapping_for_known_sel: assert property (
    @(posedge clk) disable iff (1'b0)
      (!$isunknown(sel)) |-> (
        ((sel === 2'b00) && (out == a)) ||
        ((sel === 2'b01) && (out == b)) ||
        ((sel === 2'b10) && (out == c)) ||
        ((sel === 2'b11) && (out == d))
      )
  );

  // If sel and selected input are stable, out is stable.
  check_out_stable_if_sel_and_selected_stable: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) &&
       (((sel === 2'b00) && $stable(a)) ||
        ((sel === 2'b01) && $stable(b)) ||
        ((sel === 2'b10) && $stable(c)) ||
        ((sel === 2'b11) && $stable(d))))) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==00 and a is stable.
  check_unselected_changes_ignore_out_sel00: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b00) && $stable(a) && $changed({b,c,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==01 and b is stable.
  check_unselected_changes_ignore_out_sel01: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b01) && $stable(b) && $changed({a,c,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==10 and c is stable.
  check_unselected_changes_ignore_out_sel10: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b10) && $stable(c) && $changed({a,b,d})) |-> $stable(out)
  );

  // Changes on unselected inputs do not affect out when sel==11 and d is stable.
  check_unselected_changes_ignore_out_sel11: assert property (
    @(posedge clk) disable iff (1'b0)
      ($stable(sel) && (sel === 2'b11) && $stable(d) && $changed({a,b,c})) |-> $stable(out)
  );

endmodule

verilog_code:
module Adder4 (input [3:0] A, B, input Cin, clk, output [3:0] S, output Cout);

    reg [3:0] S_reg;
    reg Cout_reg;

    always @(posedge clk) begin
        S_reg <= A + B + Cin;
        Cout_reg <= (A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin);
    end

    assign S = S_reg;
    assign Cout = Cout_reg;

endmodule

sva_code:
module Adder4_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic       clk,
    input logic [3:0] S,
    input logic       Cout
);

    // S registers the 4-bit sum A+B+Cin one cycle later.
    check_sum_registered: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S == $past(A + B + Cin))
    );

    // Cout registers the MSB carry expression one cycle later.
    check_cout_registered: assert property (
        @(posedge clk) 1'b1 |-> ##1 (Cout == $past((A[3] & B[3]) | (A[3] & Cin) | (B[3] & Cin)))
    );

    // LSB of the sum equals A[0]^B[0]^Cin one cycle later.
    check_sum_lsb_bit0: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S[0] == $past(A[0] ^ B[0] ^ Cin))
    );

    // MSB of the sum equals bit[3] of (A+B+Cin) one cycle later.
    check_sum_msb_bit3: assert property (
        @(posedge clk) 1'b1 |-> ##1 (S[3] == $past((A + B + Cin)[3]))
    );

    // Cout is independent of lower bits; if {A[3],B[3],Cin} is unchanged across two cycles, Cout holds.
    check_cout_independent_of_lower_bits: assert property (
        @(posedge clk) ($past({A[3], B[3], Cin}) == $past({A[3], B[3], Cin}, 2)) |-> ##1 (Cout == $past(Cout))
    );

endmodule

