module binary_counter_4bit(
    input clk,
    input rst_n,
    output reg [3:0] count
);

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
        if (count == 4'b1111) begin
            count <= 4'b0;
        end
    end
end

endmodule

sva_code:
module binary_counter_4bit_sva (
    input logic clk,
    input logic rst_n,
    input logic [3:0] count
);

    // When reset is asserted low at a clock edge, count must be zero.
    reset_level_forces_zero: assert property (
        @(posedge clk) (!rst_n) |-> (count == 4'b0000)
    );

    // If reset is held low across consecutive clock edges, count remains zero.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (!rst_n && $past(!rst_n)) |-> (count == 4'b0000)
    );

    // On a falling edge of rst_n (detected at the clock), count is zero.
    reset_fall_clears_count: assert property (
        @(posedge clk) $fell(rst_n) |-> (count == 4'b0000)
    );

    // On reset deassertion (rising edge of rst_n sampled at the clock), count becomes 1.
    reset_release_sets_one: assert property (
        @(posedge clk) $rose(rst_n) |-> (count == 4'b0001)
    );

    // In non-reset cycles, next value is either prior+1 (mod 16) or 1 if an async reset occurred between clocks.
    next_value_inc_or_one: assert property (
        @(posedge clk) disable iff (!rst_n)
            (count == (($past(count) + 4'd1) & 4'hF)) || (count == 4'h1)
    );

    // In non-reset cycles, observing count==0 implies prior sample was 15 (wrap event).
    zero_only_from_wrap: assert property (
        @(posedge clk) disable iff (!rst_n)
            (count == 4'h0) |-> ($past(count) == 4'hF)
    );

endmodule

verilog_code:
module bitwise_or_twos_complement (
    input [3:0] a,
    input [3:0] b,
    output reg [3:0] out
);

// Bitwise OR block
reg [3:0] or_result;
always @* begin
    or_result = a | b;
end

// 2's complement block
reg [3:0] twos_comp_result;
always @* begin
    twos_comp_result = ~or_result + 1;
end

// Difference block
reg [3:0] diff;
always @* begin
    diff = a - b;
end

// Output assignment
always @* begin
    out = twos_comp_result;
end

endmodule

sva_code:
module bitwise_or_twos_complement_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] out
);
    // out equals two's complement of (a | b).
    out_twos_comp_def: assert property (
        @(posedge clk) out == ((~(a | b)) + 4'd1)
    );

    // out plus (a | b) wraps to zero (mod 16).
    sum_with_or_zero: assert property (
        @(posedge clk) (out + (a | b)) == 4'd0
    );

    // out is zero iff both a and b are zero.
    zero_iff_a_b_zero: assert property (
        @(posedge clk) (out == 4'd0) == ((a == 4'd0) && (b == 4'd0))
    );

    // Two's complement of out yields (a | b).
    double_negation_returns_or: assert property (
        @(posedge clk) ((~out) + 4'd1) == (a | b)
    );

    // If inputs are stable, output is stable.
    stable_out_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // If (a | b) is unchanged, out is unchanged.
    stable_out_when_or_unchanged: assert property (
        @(posedge clk) ((a | b) == $past(a | b)) |-> (out == $past(out))
    );

    // If (a | b) is 8, out is also 8 (self-negating).
    or_8_maps_to_out_8: assert property (
        @(posedge clk) ((a | b) == 4'd8) |-> (out == 4'd8)
    );

    // If (a | b) is 15 (all ones), out is 1.
    or_all_ones_maps_to_one: assert property (
        @(posedge clk) ((a | b) == 4'hF) |-> (out == 4'd1)
    );

    // Nonzero (a | b) implies nonzero out.
    nonzero_or_implies_nonzero_out: assert property (
        @(posedge clk) ((a | b) != 4'd0) |-> (out != 4'd0)
    );

    // out changes only if (a | b) changes.
    out_change_implies_or_change: assert property (
        @(posedge clk) (out != $past(out)) |-> ((a | b) != $past(a | b))
    );
endmodule

verilog_code:
module top_module (
    input [2:0] a,         // 3-bit input vector a
    input [2:0] b,         // 3-bit input vector b
    input sel_logic_or,   // Select input for logical OR or bitwise OR
    input sel_inverse,    // Select input for regular or inverse input vectors
    output [2:0] out_or,   // Output from logical OR module
    output [2:0] out_bitwise,  // Output from bitwise OR module
    output [5:0] out_not   // Output for inverses of input vectors
);

    wire [2:0] a_int, b_int;
    wire [2:0] out_or_int, out_bitwise_int;

    assign a_int = sel_inverse ? ~a : a;
    assign b_int = sel_inverse ? ~b : b;

    // Instantiate the logical OR module
    or_logic_module u_or_logic (
        .a(a_int),
        .b(b_int),
        .out(out_or_int)
    );

    // Instantiate the bitwise OR module
    or_bitwise_module u_or_bitwise (
        .a(a_int),
        .b(b_int),
        .out(out_bitwise_int)
    );

    // Combinational logic for inverses
    assign out_not[5:3] = ~b;
    assign out_not[2:0] = ~a;

    // Select between logical OR and bitwise OR
    assign out_or = sel_logic_or ? out_or_int : 3'b0;
    assign out_bitwise = ~sel_logic_or ? out_bitwise_int : 3'b0;

endmodule
module or_logic_module (
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);
    assign out = a | b;
endmodule
module or_bitwise_module (
    input [2:0] a,
    input [2:0] b,
    output [2:0] out
);
    assign out = a | b;
endmodule

sva_code:
module top_module_sva (
    input logic CLK,
    input logic [2:0] a,
    input logic [2:0] b,
    input logic sel_logic_or,
    input logic sel_inverse,
    input logic [2:0] out_or,
    input logic [2:0] out_bitwise,
    input logic [5:0] out_not
);
    // Expected OR of (possibly inverted) inputs used by both output selections
    wire [2:0] expected_or = sel_inverse ? (~a | ~b) : (a | b);

    // out_not lower bits are bitwise NOT of a
    check_out_not_lower: assert property (
        @(posedge CLK) out_not[2:0] == ~a
    );

    // out_not upper bits are bitwise NOT of b
    check_out_not_upper: assert property (
        @(posedge CLK) out_not[5:3] == ~b
    );

    // When sel_logic_or=0, out_or is forced to zero
    check_out_or_zero_when_sel0: assert property (
        @(posedge CLK) (sel_logic_or == 1'b0) |-> (out_or == 3'b000)
    );

    // When sel_logic_or=1, out_bitwise is forced to zero
    check_out_bitwise_zero_when_sel1: assert property (
        @(posedge CLK) (sel_logic_or == 1'b1) |-> (out_bitwise == 3'b000)
    );

    // When sel_logic_or=1, out_or equals OR of selected (possibly inverted) inputs
    check_out_or_value_when_sel1: assert property (
        @(posedge CLK) (sel_logic_or == 1'b1) |-> (out_or == expected_or)
    );

    // When sel_logic_or=0, out_bitwise equals OR of selected (possibly inverted) inputs
    check_out_bitwise_value_when_sel0: assert property (
        @(posedge CLK) (sel_logic_or == 1'b0) |-> (out_bitwise == expected_or)
    );

    // The OR of the two outputs equals the expected OR result
    check_outputs_or_combined_equals_expected: assert property (
        @(posedge CLK) (out_or | out_bitwise) == expected_or
    );

    // The two outputs are bitwise disjoint
    check_outputs_bitwise_disjoint: assert property (
        @(posedge CLK) (out_or & out_bitwise) == 3'b000
    );

    // If out_or is zero then either it is deselected or the expected result is zero
    check_out_or_zero_implication: assert property (
        @(posedge CLK) (out_or == 3'b000) |-> ((sel_logic_or == 1'b0) || (expected_or == 3'b000))
    );

    // If out_bitwise is zero then either it is deselected or the expected result is zero
    check_out_bitwise_zero_implication: assert property (
        @(posedge CLK) (out_bitwise == 3'b000) |-> ((sel_logic_or == 1'b1) || (expected_or == 3'b000))
    );
