    // read_2 passes read_1 when EN_write_1 is LOW.
    pass_read2_when_en1_low: assert property (
        @(posedge CLK) !EN_write_1 |-> (read_2 == read_1)
    );

    // read_3 selects write_2 when EN_write_2 is HIGH.
    sel_read3_when_en2: assert property (
        @(posedge CLK) EN_write_2 |-> (read_3 == write_2)
    );
    // read_3 passes read_2 when EN_write_2 is LOW.
    pass_read3_when_en2_low: assert property (
        @(posedge CLK) !EN_write_2 |-> (read_3 == read_2)
    );

    // read_4 selects write_3 when EN_write_3 is HIGH.
    sel_read4_when_en3: assert property (
        @(posedge CLK) EN_write_3 |-> (read_4 == write_3)
    );
    // read_4 passes read_3 when EN_write_3 is LOW.
    pass_read4_when_en3_low: assert property (
        @(posedge CLK) !EN_write_3 |-> (read_4 == read_3)
    );

    // read_5 selects write_4 when EN_write_4 is HIGH.
    sel_read5_when_en4: assert property (
        @(posedge CLK) EN_write_4 |-> (read_5 == write_4)
    );
    // read_5 passes read_4 when EN_write_4 is LOW.
    pass_read5_when_en4_low: assert property (
        @(posedge CLK) !EN_write_4 |-> (read_5 == read_4)
    );

    // read_6 selects write_5 when EN_write_5 is HIGH.
    sel_read6_when_en5: assert property (
        @(posedge CLK) EN_write_5 |-> (read_6 == write_5)
    );
    // read_6 passes read_5 when EN_write_5 is LOW.
    pass_read6_when_en5_low: assert property (
        @(posedge CLK) !EN_write_5 |-> (read_6 == read_5)
    );

    ///// Collapsed passthrough to read_0 when no prior enables are set /////
    // With EN_write_1..0 LOW, read_2 equals read_0.
    no_en_1_to_0_read2_eq_read0: assert property (
        @(posedge CLK) (!EN_write_1 && !EN_write_0) |-> (read_2 == read_0)
    );
    // With EN_write_2..0 LOW, read_3 equals read_0.
    no_en_2_to_0_read3_eq_read0: assert property (
        @(posedge CLK) (!EN_write_2 && !EN_write_1 && !EN_write_0) |-> (read_3 == read_0)
    );
    // With EN_write_3..0 LOW, read_4 equals read_0.
    no_en_3_to_0_read4_eq_read0: assert property (
        @(posedge CLK) (!EN_write_3 && !EN_write_2 && !EN_write_1 && !EN_write_0) |-> (read_4 == read_0)
    );
    // With EN_write_4..0 LOW, read_5 equals read_0.
    no_en_4_to_0_read5_eq_read0: assert property (
        @(posedge CLK) (!EN_write_4 && !EN_write_3 && !EN_write_2 && !EN_write_1 && !EN_write_0) |-> (read_5 == read_0)
    );
    // With EN_write_5..0 LOW, read_6 equals read_0.
    no_en_5_to_0_read6_eq_read0: assert property (
        @(posedge CLK) (!EN_write_5 && !EN_write_4 && !EN_write_3 && !EN_write_2 && !EN_write_1 && !EN_write_0) |-> (read_6 == read_0)
    );

endmodule

verilog_code:
module logic_function (
    input A, B, Ci,
    output S, Co
);

wire n9, n10, n11;

assign n11 = ~(A ^ B);
assign S = ~(Ci ^ n11);
assign n10 = A & B & Ci;
assign n9 = ~(A & B);
assign Co = ~(n10 & n9);

endmodule

sva_code:
module logic_function_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);
    // S equals ~(Ci ^ ~(A ^ B)) as coded.
    check_sum_xnor_chain: assert property (
        @(posedge CLK) S == ~(Ci ^ ~(A ^ B))
    );

    // S equals three-input XOR of A, B, and Ci.
    check_sum_triple_xor: assert property (
        @(posedge CLK) S == (A ^ B ^ Ci)
    );

    // When A and B are equal, S mirrors Ci.
    check_sum_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (S == Ci)
    );

    // When A and B differ, S is the inverse of Ci.
    check_sum_when_AneB: assert property (
        @(posedge CLK) (A != B) |-> (S == ~Ci)
    );

    // S ^ Ci equals A ^ B (rearranged XOR identity).
    check_sum_xor_relation: assert property (
        @(posedge CLK) (S ^ Ci) == (A ^ B)
    );

    // Co equals ~( (A & B & Ci) & ~(A & B) ) as coded.
    check_carry_expr: assert property (
        @(posedge CLK) Co == ~((A & B & Ci) & ~(A & B))
    );

    // Co is constant HIGH for all input combinations (logic simplification).
    check_carry_const_high: assert property (
        @(posedge CLK) Co == 1'b1
    );
endmodule

verilog_code:
module adder(clk, rst_n, in1, in2, out);

input clk;
input rst_n;
input [7:0] in1;
input [7:0] in2;

output reg [8:0] out;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        out <= 0;
    end
    else begin
        out <= {1'b0, in1} + {1'b0, in2};
    end
end

endmodule

sva_code:
module adder_sva (
    input logic clk,
    input logic rst_n,
    input logic [7:0] in1,
    input logic [7:0] in2,
    input logic [8:0] out
);
    // When reset is asserted, out is driven to zero.
    reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 9'd0)
    );

    // Out equals previous cycle's zero-extended sum when not in reset.
    out_matches_prev_sum: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(rst_n) == 1'b1) |-> (out == $past({1'b0, in1} + {1'b0, in2}))
    );

    // Out is within the valid sum range [0..510] after an active cycle.
    out_within_range: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(rst_n) == 1'b1) |-> (out <= 9'd510)
    );

    // If inputs are unchanged over two cycles, out remains unchanged.
    out_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (!rst_n)
            (($past(rst_n) == 1'b1) && ($past(rst_n,2) == 1'b1) &&
             ($past(in1) == $past(in1,2)) && ($past(in2) == $past(in2,2)))
            |-> (out == $past(out))
    );

    // If previous inputs were both zero, next out is zero.
    zero_inputs_zero_output: assert property (
        @(posedge clk) disable iff (!rst_n)
            (($past(rst_n) == 1'b1) && ($past(in1) == 8'd0) && ($past(in2) == 8'd0))
            |-> (out == 9'd0)
    );

    // If previous inputs were both 0xFF, next out is 510.
    max_inputs_max_output: assert property (
        @(posedge clk) disable iff (!rst_n)
            (($past(rst_n) == 1'b1) && ($past(in1) == 8'hFF) && ($past(in2) == 8'hFF))
            |-> (out == 9'd510)
    );

    // With no carry from previous inputs, MSB is 0 and low byte is 8-bit sum.
    no_carry_decomposition: assert property (
        @(posedge clk) disable iff (!rst_n)
            (($past(rst_n) == 1'b1) &&
             ((({1'b0, $past(in1)} + {1'b0, $past(in2)})[8]) == 1'b0))
            |-> ((out[8] == 1'b0) && (out[7:0] == ($past(in1) + $past(in2))))
    );

    // With carry from previous inputs, MSB is 1 and low byte is 8-bit sum.
    carry_decomposition: assert property (
        @(posedge clk) disable iff (!rst_n)
            (($past(rst_n) == 1'b1) &&
             ((({1'b0, $past(in1)} + {1'b0, $past(in2)})[8]) == 1'b1))
            |-> ((out[8] == 1'b1) && (out[7:0] == ($past(in1) + $past(in2))))
    );
endmodule

verilog_code:
module barrel_shifter (
    input [3:0] data_in,
    input [1:0] control,
    output [3:0] data_out
);

    reg [3:0] temp;

    always @(*) begin
        case (control)
            2'b00: temp = {data_in[2:0], 1'b0};
            2'b01: temp = {1'b0, data_in[3:1]};
            2'b10: temp = {data_in[2:0], data_in[3]};
            2'b11: temp = {data_in[3], data_in[3:1]};
        endcase
    end

    assign data_out = temp;

endmodule

sva_code:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] control,
    input logic [3:0] data_out
);
    // Clock: none in RTL; assertions use external clk. Reset: none. Logic: purely combinational.

    // control=00: logical left shift by 1 with zero fill.
    check_sll_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b00) |-> (data_out == {data_in[2:0], 1'b0})
    );

    // control=01: logical right shift by 1 with zero fill.
    check_srl_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b01) |-> (data_out == {1'b0, data_in[3:1]})
    );

    // control=10: rotate left by 1.
    check_rol_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b10) |-> (data_out == {data_in[2:0], data_in[3]})
    );

    // control=11: arithmetic right shift by 1 (sign extension).
    check_asr_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out == {data_in[3], data_in[3:1]})
    );

    // For SLL (00), LSB must be zero (zero-fill).
    check_sll_zero_lsb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b00) |-> (data_out[0] == 1'b0)
    );

    // For SRL (01), MSB must be zero (zero-fill).
    check_srl_zero_msb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b01) |-> (data_out[3] == 1'b0)
    );

    // For ROL (10), LSB equals prior MSB.
    check_rol_lsb_is_msb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b10) |-> (data_out[0] == data_in[3])
    );

    // For ASR (11), MSB equals sign bit.
    check_asr_msb_is_sign: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out[3] == data_in[3])
    );

    // For ASR (11), bit2 equals sign bit after shift.
    check_asr_bit2_is_sign: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out[2] == data_in[3])
    );

    // If inputs are stable, output must remain stable (combinational determinism).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(control) && $stable(data_in)) |-> $stable(data_out)
    );
endmodule

