module three_input_and_sva (
    input logic CLK,   // External verification clock (DUT has no clock/reset)
    input logic VPWR,
    input logic VGND,
    input logic a,
    input logic b,
    input logic c,
    input logic out
);
    // DUT is purely combinational 3-input NAND: out = ~(a & b & c); VPWR/VGND are unused by logic.

    // Output equals NAND of a, b, c.
    check_nand_function: assert property (
        @(posedge CLK) out == ~(a & b & c)
    );

    // DeMorgan equivalent form holds.
    check_demorgan_equivalence: assert property (
        @(posedge CLK) out == (~a | ~b | ~c)
    );

    // All inputs HIGH drives out LOW.
    check_all_high_out_low: assert property (
        @(posedge CLK) (a && b && c) |-> (out == 1'b0)
    );

    // Any input LOW drives out HIGH.
    check_any_low_out_high: assert property (
        @(posedge CLK) ((!a) || (!b) || (!c)) |-> (out == 1'b1)
    );

    // a LOW alone forces out HIGH.
    check_a_zero_forces_one: assert property (
        @(posedge CLK) (!a) |-> (out == 1'b1)
    );

    // b LOW alone forces out HIGH.
    check_b_zero_forces_one: assert property (
        @(posedge CLK) (!b) |-> (out == 1'b1)
    );

    // c LOW alone forces out HIGH.
    check_c_zero_forces_one: assert property (
        @(posedge CLK) (!c) |-> (out == 1'b1)
    );

    // With b and c HIGH, out equals ~a.
    check_bc_high_out_is_not_a: assert property (
        @(posedge CLK) (b && c) |-> (out == ~a)
    );

    // With a and c HIGH, out equals ~b.
    check_ac_high_out_is_not_b: assert property (
        @(posedge CLK) (a && c) |-> (out == ~b)
    );

    // With a and b HIGH, out equals ~c.
    check_ab_high_out_is_not_c: assert property (
        @(posedge CLK) (a && b) |-> (out == ~c)
    );

endmodule

module counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [15:0] count
);

    // When reset is asserted, count must be zero on that cycle.
    reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 16'd0)
    );

    // With enable and no reset, count increments by 1 from previous value.
    inc_on_enable: assert property (
        @(posedge clk) disable iff (reset) enable |-> (count == $past(count) + 16'd1)
    );

    // With !enable and no reset, count holds its previous value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |-> (count == $past(count))
    );

    // Without reset, any change to count must be due to enable.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) $changed(count) |-> enable
    );

    // Wrap-around when previous value was 0xFFFF and enable is asserted.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) == 16'hFFFF)) |-> (count == 16'h0000)
    );

    // If enable stays high for two cycles with no reset in those cycles, count increases by 2.
    two_cycle_inc_streak: assert property (
        @(posedge clk) disable iff (reset)
            (enable && $past(enable) && !$past(reset) && !$past($past(reset)))
            |-> (count == $past($past(count)) + 16'd2)
    );

    // If enable stays low for two cycles with no reset in those cycles, count is unchanged across two cycles.
    two_cycle_hold_streak: assert property (
        @(posedge clk) disable iff (reset)
            (!enable && !$past(enable) && !$past(reset) && !$past($past(reset)))
            |-> (count == $past($past(count)))
    );

    // Reset dominates enable when both are asserted.
    reset_dominates_enable: assert property (
        @(posedge clk) (reset && enable) |-> (count == 16'd0)
    );

endmodule

module xor_gate_sva (
    input logic A,
    input logic B,
    input logic EN,
    input logic CLK,
    input logic Z
);
    // Z matches previous-cycle function: EN ? (A^B) : 0.
    check_functional_nextstate: assert property (
        @(posedge CLK) disable iff ($initstate)
            Z == ($past(EN) ? ($past(A) ^ $past(B)) : 1'b0)
    );

    // When previously disabled, Z must be 0.
    check_zero_when_disabled_prev: assert property (
        @(posedge CLK) disable iff ($initstate)
            (!$past(EN)) |-> (Z == 1'b0)
    );

    // When previously enabled, Z equals previous A^B.
    check_xor_when_enabled_prev: assert property (
        @(posedge CLK) disable iff ($initstate)
            ($past(EN)) |-> (Z == ($past(A) ^ $past(B)))
    );

    // If Z is 1 now, previous EN was 1 and previous A!=B.
    check_z_high_implies_prev_enable_unequal: assert property (
        @(posedge CLK) disable iff ($initstate)
            (Z == 1'b1) |-> ($past(EN) && ($past(A) ^ $past(B)))
    );

    // If Z is 0 now with previous EN=1, previous A==B.
    check_z_low_with_enable_implies_prev_inputs_equal: assert property (
        @(posedge CLK) disable iff ($initstate)
            ($past(EN) && (Z == 1'b0)) |-> (~($past(A) ^ $past(B)))
    );

    // A rising edge on Z only occurs if previously EN=1 and A!=B.
    check_rose_z_cause: assert property (
        @(posedge CLK) disable iff ($initstate)
            $rose(Z) |-> ($past(EN) && ($past(A) ^ $past(B)))
    );

    // A falling edge on Z only occurs if previously EN=0 or A==B.
    check_fell_z_cause: assert property (
        @(posedge CLK) disable iff ($initstate)
            $fell(Z) |-> ((!$past(EN)) || (~($past(A) ^ $past(B))))
    );
endmodule

