module sky130_fd_sc_hdll__and3_sva (
    input logic X,
    input logic A,
    input logic B,
    input logic C
);
    // No clock/reset in RTL; pure combinational AND3 with buffer to X.
    // Assertions are sampled on any edge of A, B, C, or X.

    // X must equal A & B & C at all times.
    check_functional_equivalence: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            X == (A & B & C)
    );

    // If any input is 0, X must be 0.
    check_zero_dominance: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            ((!A) || (!B) || (!C)) |-> (X == 1'b0)
    );

    // If all inputs are 1, X must be 1.
    check_all_high_implies_one: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && B && C) |-> (X == 1'b1)
    );

    // A&B high makes X follow C.
    check_ab_high_passthru_c: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && B) |-> (X == C)
    );

    // A&C high makes X follow B.
    check_ac_high_passthru_b: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (A && C) |-> (X == B)
    );

    // B&C high makes X follow A.
    check_bc_high_passthru_a: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            (B && C) |-> (X == A)
    );

    // A rising transition of the 3-input AND forces X to rise.
    check_and_rise_causes_x_rise: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $rose(A && B && C) |-> $rose(X)
    );

    // A falling transition of the 3-input AND forces X to fall.
    check_and_fall_causes_x_fall: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $fell(A && B && C) |-> $fell(X)
    );

    // X can only rise when all inputs are 1.
    check_x_rise_requires_all_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $rose(X) |-> (A && B && C)
    );

    // X can only fall when not all inputs are 1.
    check_x_fall_requires_not_all_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $fell(X) |-> !(A && B && C)
    );

    // Any change on X must be due to a change on at least one input.
    check_x_change_requires_input_change: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge X or negedge X)
            $changed(X) |-> ($changed(A) || $changed(B) || $changed(C))
    );

endmodule

module multi_input_output_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] D,
    input logic [7:0] E,
    input logic [7:0] F,
    input logic [7:0] G,
    input logic [7:0] H,
    input logic [7:0] Y
);

    ///// Functional correctness /////
    // Y equals (A+B)-(C+D)+(E+F)-(G+H) with 8-bit wrap.
    check_y_definition: assert property (
        @(posedge A[0]) Y == (A + B) - (C + D) + (E + F) - (G + H)
    );

    // All inputs zero yields Y=0.
    check_y_all_zero_input: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==8'h00)
    );

    // If B..H are zero, Y passes A.
    check_y_passthrough_A_when_others_zero: assert property (
        @(posedge A[0]) ((B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==A)
    );

    // If pairwise inputs match (A=C,B=D,E=G,F=H), Y is zero.
    check_y_zero_when_pairs_equal: assert property (
        @(posedge A[0]) ((A==C)&&(B==D)&&(E==G)&&(F==H))
        |-> (Y==8'h00)
    );

    // If E=F=G=H=0, Y=(A+B)-(C+D).
    check_y_when_EFGH_zero: assert property (
        @(posedge A[0]) ((E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D))
    );

    // If G=H=0, Y=(A+B)-(C+D)+(E+F).
    check_y_when_GH_zero: assert property (
        @(posedge A[0]) ((G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D) + (E + F))
    );

    // If A=B=C=D=0, Y=(E+F)-(G+H).
    check_y_when_ABCD_zero: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00))
        |-> (Y == (E + F) - (G + H))
    );

    ///// Algebraic cancellation checks (mod-256 arithmetic) /////
    // Adding back (G+H) cancels the final subtraction.
    check_cancel_gh_addback: assert property (
        @(posedge A[0]) (Y + (G + H)) == ( (A + B) - (C + D) + (E + F) )
    );

    // Adding back (G+H) then subtracting (E+F) cancels the last two pairs.
    check_cancel_gh_then_ef: assert property (
        @(posedge A[0]) ((Y + (G + H)) - (E + F)) == ( (A + B) - (C + D) )
    );

    // After canceling GH and EF and adding (C+D), recover (A+B).
    check_recover_ab: assert property (
        @(posedge A[0]) (((Y + (G + H)) - (E + F)) + (C + D)) == (A + B)
    );

endmodule

