verilog_code:
module multifsm(clk, rst, proddone, start, done, ld, shift);

  input clk;
  input rst; 
  input start;
  input proddone;
  output  done;
  output   ld;
  output shift;

  parameter [1:0] IDLE=2'b00, MUL=2'b01 , DONE= 2'b10;
  reg [1:0] state , newstate;

  always @* begin
    newstate = IDLE;
    case (state)
        IDLE: if (start) newstate= MUL; else newstate= IDLE;
        MUL: if (start & proddone) newstate = DONE; else if (start) newstate = MUL; else newstate = IDLE;
        DONE: if(start) newstate= DONE ; else newstate= IDLE;
    endcase

    end

  always @( posedge clk or posedge rst)
         if (rst)
              state <= IDLE;
         else state <= newstate;

  assign done  = (state == DONE);
  assign ld    = (state == IDLE);
  assign shift = (state== MUL) && !proddone;


endmodule

sva_code:
module multifsm_sva (
    input logic clk,
    input logic rst,
    input logic proddone,
    input logic start,
    input logic done,
    input logic ld,
    input logic shift,
    input logic [1:0] state,
    input logic [1:0] newstate
);
    // State encodings mirrored from RTL
    localparam logic [1:0] IDLE = 2'b00;
    localparam logic [1:0] MUL  = 2'b01;
    localparam logic [1:0] DONE = 2'b10;

    ///// Reset behavior /////
    // When reset is asserted, state must be IDLE.
    reset_state_idle: assert property (
        @(posedge clk) rst |-> (state == IDLE)
    );
    // When reset is asserted, outputs reflect IDLE (ld=1, done=0, shift=0).
    reset_outputs_idle: assert property (
        @(posedge clk) rst |-> (ld == 1'b1) && (done == 1'b0) && (shift == 1'b0)
    );

    ///// Sequential update /////
    // When not in reset, state updates from previous cycle's newstate.
    check_state_uses_newstate: assert property (
        @(posedge clk) disable iff (rst) state == $past(newstate)
    );

    ///// Next-state combinational logic /////
    // newstate calculation when in IDLE.
    nextstate_calc_idle: assert property (
        @(posedge clk) disable iff (rst) (state == IDLE) |-> (newstate == (start ? MUL : IDLE))
    );
    // newstate calculation when in MUL.
    nextstate_calc_mul: assert property (
        @(posedge clk) disable iff (rst) (state == MUL) |-> (newstate == ((start && proddone) ? DONE : (start ? MUL : IDLE)))
    );
    // newstate calculation when in DONE.
    nextstate_calc_done: assert property (
        @(posedge clk) disable iff (rst) (state == DONE) |-> (newstate == (start ? DONE : IDLE))
    );

    ///// Output decode /////
    // done is high iff state == DONE.
    check_done_decode: assert property (
        @(posedge clk) disable iff (rst) (done == (state == DONE))
    );
    // ld is high iff state == IDLE.
    check_ld_decode: assert property (
        @(posedge clk) disable iff (rst) (ld == (state == IDLE))
    );
    // shift is high iff state == MUL and proddone == 0.
    check_shift_decode: assert property (
        @(posedge clk) disable iff (rst) (shift == ((state == MUL) && !proddone))
    );
    // Shift equals (!done && !ld && !proddone).
    check_shift_vs_outputs: assert property (
        @(posedge clk) disable iff (rst) (shift == (!done && !ld && !proddone))
    );
    // ld and done are mutually exclusive.
    check_ld_done_mutex: assert property (
        @(posedge clk) disable iff (rst) !(ld && done)
    );

    ///// Temporal behavior from outputs /////
    // In DONE, next-cycle done equals current start.
    done_next_depends_on_start: assert property (
        @(posedge clk) disable iff (rst) done |-> ##1 (done == start)
    );
    // If ld and start==0, remain in IDLE next cycle (ld stays high).
    ld_holds_when_start_low: assert property (
        @(posedge clk) disable iff (rst) (ld && !start) |-> ##1 ld
    );
    // If ld and start==1, leave IDLE next cycle (ld goes low).
    ld_clears_when_start_high: assert property (
        @(posedge clk) disable iff (rst) (ld && start) |-> ##1 !ld
    );
    // From MUL with start && proddone, go to DONE next cycle.
    mul_to_done_on_start_and_proddone: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && start && proddone) |-> ##1 done
    );
    // From MUL with start && !proddone, stay in MUL next cycle.
    mul_stay_when_start_and_not_proddone: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && start && !proddone) |-> ##1 (!ld && !done)
    );
    // From MUL with !start, go to IDLE next cycle.
    mul_to_idle_when_start_low: assert property (
        @(posedge clk) disable iff (rst) (!ld && !done && !start) |-> ##1 ld
    );
    // A rising edge of done occurs only from MUL with start && proddone in the previous cycle.
    done_rise_from_mul_start_proddone: assert property (
        @(posedge clk) disable iff (rst) $rose(done) |-> ($past(!ld && !done) && $past(start) && $past(proddone))
    );
    // A falling edge of ld occurs only if start was high in the previous cycle.
    ld_fall_requires_start_high: assert property (
        @(posedge clk) disable iff (rst) $fell(ld) |-> $past(start)
    );
    // A rising edge of ld occurs only if start was low in the previous cycle.
    ld_rise_requires_start_low: assert property (
        @(posedge clk) disable iff (rst) $rose(ld) |-> !$past(start)
    );
    // A falling edge of done occurs only if start was low in the previous cycle.
    done_fall_requires_start_low: assert property (
        @(posedge clk) disable iff (rst) $fell(done) |-> !$past(start)
    );
endmodule

verilog_code:
module decoder_3to8 (
    input [2:0] in,
    input en,
    output reg [7:0] out
);

always @(*) begin
    if (en == 1'b0) begin
        out <= 8'b00000000;
    end else begin
        case (in)
            3'b000: out <= 8'b00000001;
            3'b001: out <= 8'b00000010;
            3'b010: out <= 8'b00000100;
            3'b011: out <= 8'b00001000;
            3'b100: out <= 8'b00010000;
            3'b101: out <= 8'b00100000;
            3'b110: out <= 8'b01000000;
            3'b111: out <= 8'b10000000;
        endcase
    end
end

endmodule

sva_code:
module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] in,
    input logic en,
    input logic [7:0] out
);
    ///// Decoder correctness /////
    // When disabled, all outputs must be 0.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) (en == 1'b0) |-> (out == 8'b00000000)
    );

    // When enabled, output must be non-zero.
    check_out_nonzero_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> (out != 8'b00000000)
    );

    // When enabled, output must be one-hot.
    check_onehot_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> $onehot(out)
    );

    // When enabled and in==000, out must be 00000001.
    check_decode_case_0: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b000) |-> (out == 8'b00000001)
    );

    // When enabled and in==001, out must be 00000010.
    check_decode_case_1: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b001) |-> (out == 8'b00000010)
    );

    // When enabled and in==010, out must be 00000100.
    check_decode_case_2: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b010) |-> (out == 8'b00000100)
    );

    // When enabled and in==011, out must be 00001000.
    check_decode_case_3: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b011) |-> (out == 8'b00001000)
    );

    // When enabled and in==100, out must be 00010000.
    check_decode_case_4: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b100) |-> (out == 8'b00010000)
    );

    // When enabled and in==101, out must be 00100000.
    check_decode_case_5: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b101) |-> (out == 8'b00100000)
    );

    // When enabled and in==110, out must be 01000000.
    check_decode_case_6: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b110) |-> (out == 8'b01000000)
    );

    // When enabled and in==111, out must be 10000000.
    check_decode_case_7: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b111) |-> (out == 8'b10000000)
    );

    // If any output bit is high, enable must be high.
    check_out_high_implies_enabled: assert property (
        @(posedge clk) (|out) |-> (en == 1'b1)
    );

    // When enabled, the bit at index 'in' must be high.
    check_selected_bit_high_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> (out[in] == 1'b1)
    );
endmodule

verilog_code:
module four_bit_adder (
	input [3:0] A,
	input [3:0] B,
	input Cin,
	output [3:0] S,
	output Cout
);

	wire [3:0] X;
	wire [3:0] Y;
	wire C1, C2, C3;

	// Define NAND gate using primitive gates
	assign X[0] = ~(A[0] & B[0]);
	assign Y[0] = ~(X[0] & Cin);
	assign C1 = ~(B[0] & Cin);

	assign X[1] = ~(A[1] & B[1]);
	assign Y[1] = ~(X[1] & C1);
	assign C2 = ~(B[1] & C1);

	assign X[2] = ~(A[2] & B[2]);
	assign Y[2] = ~(X[2] & C2);
	assign C3 = ~(B[2] & C2);

	assign X[3] = ~(A[3] & B[3]);
	assign S[3] = ~(X[3] & C3);
	assign Cout = ~(B[3] & C3);

	assign S[2] = Y[2];
	assign S[1] = Y[1];
	assign S[0] = Y[0];
endmodule

sva_code:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // No clock/reset in DUT; purely combinational NAND network. Assertions sample at posedge CLK; no reset gating.

    ///// Functional equivalence to RTL equations /////
    // S[0] equals ~(~(A0 & B0) & Cin).
    check_s0_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[0] === ~( (~(A[0] & B[0])) & Cin )
    );

    // S[1] equals ~(~(A1 & B1) & ~(B0 & Cin)).
    check_s1_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[1] === ~( (~(A[1] & B[1])) & ~(B[0] & Cin) )
    );

    // S[2] equals ~(~(A2 & B2) & ~(B1 & ~(B0 & Cin))).
    check_s2_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[2] === ~( (~(A[2] & B[2])) & ~(B[1] & ~(B[0] & Cin)) )
    );

    // S[3] equals ~(~(A3 & B3) & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_s3_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[3] === ~( (~(A[3] & B[3])) & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

    // Cout equals ~(B3 & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_cout_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        Cout === ~( B[3] & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

    ///// Combinational stability /////
    // If inputs are stable, outputs must be stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );

    // Outputs can change only if at least one input changed.
    check_outputs_change_requires_input_change: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($changed(S) || $changed(Cout)) |-> ($changed(A) || $changed(B) || $changed(Cin))
    );

    ///// Independence from irrelevant inputs /////
    // S[0] is independent of A[3:1] and B[3:1] when A[0],B[0],Cin are stable.
    check_s0_independent_of_upper_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[0]) && $stable(B[0]) && $stable(Cin) && $changed({A[3:1],B[3:1]})) |-> $stable(S[0])
    );

    // S[1] is independent of A[3:2],A[0],B[3:2] when A[1],B[1],B[0],Cin are stable.
    check_s1_independent_of_irrelevant_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[1]) && $stable(B[1]) && $stable(B[0]) && $stable(Cin) && $changed({A[3:2],A[0],B[3:2]})) |-> $stable(S[1])
    );

    // S[2] is independent of A[3],A[1:0],B[3] when A[2],B[2],B[1],B[0],Cin are stable.
    check_s2_independent_of_irrelevant_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[2]) && $stable(B[2]) && $stable(B[1]) && $stable(B[0]) && $stable(Cin) && $changed({A[3],A[1:0],B[3]})) |-> $stable(S[2])
    );

    // S[3] is independent of A[2:0] when A[3],B[3:0],Cin are stable.
    check_s3_independent_of_lower_A_bits: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(A[3]) && $stable(B) && $stable(Cin) && $changed(A[2:0])) |-> $stable(S[3])
    );

    // Cout is independent of A when B and Cin are stable.
    check_cout_independent_of_A: assert property (
        @(posedge CLK) disable iff (1'b0)
        ($stable(B) && $stable(Cin) && $changed(A)) |-> $stable(Cout)
    );

    ///// Simple corner case implied by the NAND structure /////
    // When B==0, S[3:1]==0, S[0]==~Cin, Cout==1.
    check_behavior_when_B_is_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (B === 4'b0000) |-> ((S[3:1] === 3'b000) && (S[0] === ~Cin) && (Cout === 1'b1))
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);

    // Reset high drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

    // With enable low, count holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> (count == $past(count))
    );

    // With enable high and below max, count increments by 1.
    check_increment_when_enabled_not_max: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) != 4'hF)) |-> (count == $past(count) + 1)
    );

    // With enable high at max, count wraps to zero.
    check_wrap_to_zero_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

    // Any change in count requires enable high.
    check_change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) (count != $past(count)) |-> enable
    );

    // If count increments by 1, enable must be high.
    check_increment_implies_enable: assert property (
        @(posedge clk) disable iff (reset) (count == ($past(count) + 1)) |-> enable
    );

    // A decrease across cycles can only be wrap 15->0.
    check_decrease_only_on_wrap: assert property (
        @(posedge clk) disable iff (reset) (count < $past(count)) |-> (($past(count) == 4'hF) && (count == 4'h0))
    );

    // A 15->0 wrap requires enable high.
    check_wrap_transition_requires_enable: assert property (
        @(posedge clk) disable iff (reset) (($past(count) == 4'hF) && (count == 4'h0)) |-> enable
    );

    // With enable high and count is zero, previous must be 15 (not due to reset).
    check_zero_with_enable_prev_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'h0) && $past(1'b1)) |-> ($past(count) == 4'hF)
    );

    // With enable low and previous 15, count stays 15.
    check_max_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (($past(count) == 4'hF) && !enable) |-> (count == 4'hF)
    );

endmodule

