verilog_code:
module ripple_carry_adder (
  input [3:0] A,
  input [3:0] B,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] carry;

  full_adder FA0(A[0], B[0], carry_in, sum[0], carry[0]);
  full_adder FA1(A[1], B[1], carry[0], sum[1], carry[1]);
  full_adder FA2(A[2], B[2], carry[1], sum[2], carry[2]);
  full_adder FA3(A[3], B[3], carry[2], sum[3], carry_out);

endmodule
module full_adder (
  input A,
  input B,
  input C_in,
  output S,
  output C_out
);

  assign S = A ^ B ^ C_in;
  assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva_code:
module ripple_carry_adder_sva (
  input logic [3:0] A,
  input logic [3:0] B,
  input logic       carry_in,
  input logic [3:0] sum,
  input logic       carry_out
);
  // Combinational DUT with no clock/reset; assertions use $global_clock.

  // Local expected propagate/generate and carry chain computed from DUT inputs.
  wire [3:0] p = A ^ B;
  wire [3:0] g = A & B;

  wire [3:0] c;
  assign c[0] = carry_in;
  assign c[1] = g[0] | (p[0] & c[0]);
  assign c[2] = g[1] | (p[1] & c[1]);
  assign c[3] = g[2] | (p[2] & c[2]);

  wire       c4 = g[3] | (p[3] & c[3]);
  wire [4:0] expected = {1'b0, A} + {1'b0, B} + carry_in;

  // Sum+carry equals arithmetic addition of operands and carry_in.
  check_add_packed: assert property (
    @(posedge $global_clock) {carry_out, sum} == expected
  );

  // Bit 0 sum is XOR of A[0], B[0], and carry_in.
  sum_bit0_eq: assert property (
    @(posedge $global_clock) sum[0] == (p[0] ^ c[0])
  );

  // Bit 1 sum is XOR of A[1]^B[1] with carry into bit 1.
  sum_bit1_eq: assert property (
    @(posedge $global_clock) sum[1] == (p[1] ^ c[1])
  );

  // Bit 2 sum is XOR of A[2]^B[2] with carry into bit 2.
  sum_bit2_eq: assert property (
    @(posedge $global_clock) sum[2] == (p[2] ^ c[2])
  );

  // Bit 3 sum is XOR of A[3]^B[3] with carry into bit 3.
  sum_bit3_eq: assert property (
    @(posedge $global_clock) sum[3] == (p[3] ^ c[3])
  );

  // Carry-out equals ripple chain carry from bit 3.
  carry_out_eq_chain: assert property (
    @(posedge $global_clock) carry_out == c4
  );

  // Sum equals propagate XOR carry vector.
  sum_vector_eq: assert property (
    @(posedge $global_clock) sum == (p ^ {c[3], c[2], c[1], c[0]})
  );

  // Carry-out equals overflow bit of the arithmetic result.
  carry_out_matches_overflow: assert property (
    @(posedge $global_clock) carry_out == expected[4]
  );

  // If inputs are stable across a cycle, outputs are stable.
  outputs_stable_when_inputs_stable: assert property (
    @(posedge $global_clock) $stable({A, B, carry_in}) |-> $stable({sum, carry_out})
  );

  // Known inputs imply known outputs.
  outputs_known_when_inputs_known: assert property (
    @(posedge $global_clock) !$isunknown({A, B, carry_in}) |-> !$isunknown({sum, carry_out})
  );

  // Adding zero (B=0, carry_in=0) returns A with no carry.
  add_zero_identity: assert property (
    @(posedge $global_clock) (B == 4'b0000) && (carry_in == 1'b0) |-> (sum == A) && (carry_out == 1'b0)
  );
endmodule

verilog_code:
module fsm_rising_edge_counter (
  input clk,
  input in,
  output reg[2:0] count
);

  reg d_last;
  reg[1:0] state;

  parameter IDLE = 2'b00;
  parameter COUNT = 2'b01;

  always @(posedge clk) begin
    case(state)
      IDLE:
        if(in && !d_last) begin
          state <= COUNT;
          count <= 0;
        end
      COUNT:
        if(in && !d_last) begin
          if(count == 4) begin
            state <= IDLE;
          end
          else begin
            count <= count + 1;
          end
        end
        else begin
          state <= IDLE;
        end
    endcase
    d_last <= in;
  end

endmodule

sva_code:
module fsm_rising_edge_counter_sva (
    input logic clk,
    input logic in,
    input logic [2:0] count,
    input logic d_last,
    input logic [1:0] state
);
    // Mirror DUT state encodings
    localparam [1:0] IDLE  = 2'b00;
    localparam [1:0] COUNT = 2'b01;

    // d_last captures previous value of in each cycle.
    check_d_last_tracks_in_prev: assert property (
        @(posedge clk) !$isunknown($past(in)) |-> (d_last == $past(in))
    );

    // In IDLE, a rising edge (in && !d_last) causes next state COUNT and count reset to 0.
    check_idle_rise_enters_count_and_resets: assert property (
        @(posedge clk) (state == IDLE) && (in && !d_last) |=> (state == COUNT) && (count == 3'd0)
    );

    // In COUNT with no rising edge, next state goes to IDLE.
    check_count_no_rise_goes_idle: assert property (
        @(posedge clk) (state == COUNT) && !(in && !d_last) |=> (state == IDLE)
    );

    // In COUNT with a rising edge and count != 4, next cycle increments count and stays in COUNT.
    check_count_rise_incr_and_stay: assert property (
        @(posedge clk) (state == COUNT) && (in && !d_last) && (count != 3'd4) |=> (state == COUNT) && (count == $past(count) + 1)
    );

    // In COUNT with a rising edge and count == 4, next cycle goes to IDLE.
    check_count_rise_at4_goes_idle: assert property (
        @(posedge clk) (state == COUNT) && (in && !d_last) && (count == 3'd4) |=> (state == IDLE)
    );

    // Entering COUNT must come from IDLE on a rising edge.
    check_enter_count_requires_idle_rise: assert property (
        @(posedge clk) (state == COUNT) && ($past(state) != COUNT) |-> ($past(state) == IDLE) && $past(in) && !$past(d_last)
    );

    // Staying in COUNT across cycles requires a prior rising edge and count != 4.
    check_stay_in_count_requires_prev_rise_not4: assert property (
        @(posedge clk) ($past(state) == COUNT) && (state == COUNT) |-> $past(in) && !$past(d_last) && ($past(count) != 3'd4)
    );

    // From IDLE with no rising edge, remain in IDLE.
    check_idle_stays_idle_without_rise: assert property (
        @(posedge clk) ($past(state) == IDLE) && (!$past(in) || $past(d_last)) |-> (state == IDLE)
    );

    // Any change to count must be due to the defined update cases.
    check_count_changes_only_when_expected: assert property (
        @(posedge clk)
            (!$isunknown($past(count))) && (count != $past(count)) |-> 
            (
                // From IDLE on rising: count becomes 0
                (($past(state) == IDLE)  && $past(in) && !$past(d_last) && (count == 3'd0))
                ||
                // From COUNT on rising when count != 4: increment
                (($past(state) == COUNT) && $past(in) && !$past(d_last) && ($past(count) != 3'd4) && (count == $past(count) + 1))
            )
    );

    // Leaving COUNT to IDLE must be due to either no rising edge or rising with count==4.
    check_count_to_idle_has_valid_cause: assert property (
        @(posedge clk) ($past(state) == COUNT) && (state == IDLE) |-> 
            (!$past(in) || $past(d_last)) || ( $past(in) && !$past(d_last) && ($past(count) == 3'd4) )
    );

endmodule

