module mux4to1_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic S0,
    input logic S1,
    input logic Y
);
    // Y equals the LSB of the RTL mux expression.
    check_y_matches_rtl_expr_lsb: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            Y == (((S1 & S0 & D) | (S1 & ~S0 & C) | (~S1 & S0 & B) | (~S1 & ~S0 & A))[0])
    );

    // When S1=0 and S0=0, Y equals A[0].
    check_sel_00_to_A0: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (~S1 && ~S0) |-> (Y == A[0])
    );

    // When S1=0 and S0=1, Y equals B[0].
    check_sel_01_to_B0: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (~S1 && S0) |-> (Y == B[0])
    );

    // When S1=1 and S0=0, Y equals C[0].
    check_sel_10_to_C0: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1 && ~S0) |-> (Y == C[0])
    );

    // When S1=1 and S0=1, Y equals D[0].
    check_sel_11_to_D0: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            (S1 && S0) |-> (Y == D[0])
    );

    // If all LSBs are equal, Y must equal that common value.
    check_y_equal_when_all_lsbs_equal: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            ((A[0] == B[0]) && (B[0] == C[0]) && (C[0] == D[0])) |-> (Y == A[0])
    );

    // If all LSBs are 0, Y must be 0 regardless of select.
    check_y_zero_when_all_lsbs_zero: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            ((A[0] == 1'b0) && (B[0] == 1'b0) && (C[0] == 1'b0) && (D[0] == 1'b0)) |-> (Y == 1'b0)
    );

    // If all LSBs are 1, Y must be 1 regardless of select.
    check_y_one_when_all_lsbs_one: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            ((A[0] == 1'b1) && (B[0] == 1'b1) && (C[0] == 1'b1) && (D[0] == 1'b1)) |-> (Y == 1'b1)
    );

    // Decode terms are mutually exclusive (only one select term can be 1).
    check_decode_onehot: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
          !((~S1 & ~S0) && (~S1 & S0)) &&
          !((~S1 & ~S0) && (S1 & ~S0)) &&
          !((~S1 & ~S0) && (S1 & S0)) &&
          !((~S1 & S0) && (S1 & ~S0)) &&
          !((~S1 & S0) && (S1 & S0)) &&
          !((S1 & ~S0) && (S1 & S0))
    );

    // Y equals nested ternary version of the mux on the LSB.
    check_mux_with_ternary_lsb: assert property (
        @(posedge S0 or negedge S0 or posedge S1 or negedge S1)
            Y == ( S1 ? ( S0 ? D[0] : C[0] ) : ( S0 ? B[0] : A[0] ) )
    );
endmodule

verilog_code:
module IF_ID(clk,rst,if_pcplus4, stall, BJ,
	if_instr,id_pcplus4, id_instr,if_pc,id_pc
    );
	input clk,rst,stall, BJ;
	input wire [31:0] if_pcplus4,if_instr,if_pc;
	output reg [31:0] id_pcplus4,id_instr,id_pc;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			id_pcplus4 <= 4;
			id_instr <= 32'b100000;
			id_pc<=0;
		end
		else if(stall | BJ)
		begin
			id_pcplus4 <= if_pcplus4;
			id_instr <= 32'b100000;
			id_pc<=if_pc;
		end
		else
		begin
			id_pcplus4 <= if_pcplus4;
			id_instr <= if_instr;
			id_pc<=if_pc;
		end
	end
endmodule

sva_code:
module IF_ID_sva (
    input logic clk,
    input logic rst,
    input logic stall,
    input logic BJ,
    input logic [31:0] if_pcplus4,
    input logic [31:0] if_instr,
    input logic [31:0] if_pc,
    input logic [31:0] id_pcplus4,
    input logic [31:0] id_instr,
    input logic [31:0] id_pc
);
    // During reset, id_pcplus4 drives 4.
    reset_id_pcplus4_value: assert property (
        @(posedge clk) rst |-> (id_pcplus4 == 32'd4)
    );
    // During reset, id_instr drives 32'b100000.
    reset_id_instr_value: assert property (
        @(posedge clk) rst |-> (id_instr == 32'b100000)
    );
    // During reset, id_pc drives 0.
    reset_id_pc_value: assert property (
        @(posedge clk) rst |-> (id_pc == 32'd0)
    );

    // id_pcplus4 captures if_pcplus4 each cycle (1-cycle latency).
    capture_id_pcplus4_every_cycle: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> (id_pcplus4 == $past(if_pcplus4))
    );
    // id_pc captures if_pc each cycle (1-cycle latency).
    capture_id_pc_every_cycle: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> (id_pc == $past(if_pc))
    );

    // If stall or BJ in the previous cycle, id_instr flushes to 32'b100000.
    id_instr_flush_on_stall_or_BJ: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && (stall | BJ)) |-> (id_instr == 32'b100000)
    );
    // If neither stall nor BJ in the previous cycle, id_instr captures if_instr.
    id_instr_capture_when_no_stall_or_BJ: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && !(stall | BJ)) |-> (id_instr == $past(if_instr))
    );

    // A change in id_pcplus4 implies if_pcplus4 changed one cycle earlier.
    id_pcplus4_change_implies_input_change: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst,2) && (id_pcplus4 != $past(id_pcplus4))) |-> ($past(if_pcplus4) != $past(if_pcplus4,2))
    );
    // A change in id_pc implies if_pc changed one cycle earlier.
    id_pc_change_implies_input_change: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst,2) && (id_pc != $past(id_pc))) |-> ($past(if_pc) != $past(if_pc,2))
    );

    // On stall or BJ, id_pcplus4 and id_pc still update from IF stage.
    id_pc_updates_on_stall_or_BJ: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && (stall | BJ)) |-> (id_pcplus4 == $past(if_pcplus4)) && (id_pc == $past(if_pc))
    );
    // With no stall or BJ, id_pcplus4 and id_pc update from IF stage.
    id_pc_updates_when_no_stall_or_BJ: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && !(stall | BJ)) |-> (id_pcplus4 == $past(if_pcplus4)) && (id_pc == $past(if_pc))
    );
endmodule

module up_counter_3bit_sva (
    input logic clk,
    input logic reset,
    input logic [2:0] count
);

    // If reset is asserted on this clock, count is 0 on the next clock.
    check_sync_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

    // If reset was asserted in the previous cycle, count must be 0 now.
    check_prev_reset_zero_now: assert property (
        @(posedge clk) $past(reset) |-> (count == 3'd0)
    );

    // When not in reset in the previous cycle, count increments by 1 modulo 8.
    check_increment_when_prev_not_reset: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) |-> (count == ($past(count) + 3'd1))
    );

    // Explicit wraparound: from 7 to 0 when previous cycle was not in reset.
    check_wrap_7_to_0: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // While reset is held across consecutive cycles, count stays at 0.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 3'd0)
    );

    // First value after reset release is 1 (incrementing from 0 assigned during reset).
    check_first_value_after_reset_release: assert property (
        @(posedge clk) (!reset && $past(reset)) |=> (count == 3'd1)
    );

endmodule

