module mux4to1 (
    input A,
    input B,
    input C,
    input D,
    input sel0,
    input sel1,
    output Y
);

    wire w1, w2, w3, w4, w5, w6;

    assign w1 = (~sel1 & ~sel0) ? A : 1'b0;
    assign w2 = (~sel1 & sel0) ? B : 1'b0;
    assign w3 = (sel1 & ~sel0) ? C : 1'b0;
    assign w4 = (sel1 & sel0) ? D : 1'b0;

    assign w5 = w1 | w2;
    assign w6 = w3 | w4;

    assign Y = w5 | w6;

endmodule

sva_code:
module mux4to1_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic sel0,
    input logic sel1,
    input logic Y
);
    // No clock/reset in DUT; pure combinational 4:1 mux with sel1:sel0 selecting D,C,B,A.

    // Y matches the mux boolean equation at any input/select edge.
    check_functional_eq: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        Y == ((~sel1 & ~sel0 & A) | (~sel1 & sel0 & B) | (sel1 & ~sel0 & C) | (sel1 & sel0 & D))
    );

    // When sel1:sel0 == 2'b00, Y equals A.
    check_sel00_routes_A: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        (~sel1 & ~sel0) |-> (Y == A)
    );

    // When sel1:sel0 == 2'b01, Y equals B.
    check_sel01_routes_B: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        (~sel1 & sel0) |-> (Y == B)
    );

    // When sel1:sel0 == 2'b10, Y equals C.
    check_sel10_routes_C: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        (sel1 & ~sel0) |-> (Y == C)
    );

    // When sel1:sel0 == 2'b11, Y equals D.
    check_sel11_routes_D: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        (sel1 & sel0) |-> (Y == D)
    );

    // If sel1:sel0 == 2'b00 and Y is HIGH, then A must be HIGH.
    check_sel00_y_high_implies_a_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        ((~sel1 & ~sel0) && (Y == 1'b1)) |-> (A == 1'b1)
    );

    // If sel1:sel0 == 2'b01 and Y is HIGH, then B must be HIGH.
    check_sel01_y_high_implies_b_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        ((~sel1 & sel0) && (Y == 1'b1)) |-> (B == 1'b1)
    );

    // If sel1:sel0 == 2'b10 and Y is HIGH, then C must be HIGH.
    check_sel10_y_high_implies_c_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        ((sel1 & ~sel0) && (Y == 1'b1)) |-> (C == 1'b1)
    );

    // If sel1:sel0 == 2'b11 and Y is HIGH, then D must be HIGH.
    check_sel11_y_high_implies_d_high: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        ((sel1 & sel0) && (Y == 1'b1)) |-> (D == 1'b1)
    );

    // If sel1:sel0 == 2'b00 and A is LOW, Y must be LOW.
    check_sel00_a_low_implies_y_low: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge C or negedge C or posedge D or negedge D or posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
        ((~sel1 & ~sel0) && (A == 1'b0)) |-> (Y == 1'b0)
    );

endmodule

module flip_flop_sva (
    input logic D,
    input logic SET,
    input logic SLEEP_B,
    input logic KAPWR,
    input logic VGND,
    input logic VPWR,
    input logic Q,
    input logic CLK
);

    // Next-state function: Q_next = (SET ? 1 : (SLEEP_B ? 0 : D)).
    check_next_state_function: assert property (
        @(posedge CLK) 1'b1 |=> (Q == (SET ? 1'b1 : (SLEEP_B ? 1'b0 : D)))
    );

    // SET forces Q to 1 on the next clock.
    check_set_forces_one: assert property (
        @(posedge CLK) SET |=> (Q == 1'b1)
    );

    // When both SET and SLEEP_B are high, SET has priority and Q becomes 1.
    check_set_overrides_sleep: assert property (
        @(posedge CLK) (SET && SLEEP_B) |=> (Q == 1'b1)
    );

    // With SET low and SLEEP_B high, Q is cleared to 0.
    check_sleep_clears_when_no_set: assert property (
        @(posedge CLK) (!SET && SLEEP_B) |=> (Q == 1'b0)
    );

    // With both SET and SLEEP_B low, Q captures D.
    check_passthrough_d_when_no_controls: assert property (
        @(posedge CLK) (!SET && !SLEEP_B) |=> (Q == D)
    );

    // With no controls and D=1, Q becomes 1 next cycle.
    check_d1_captured_when_no_controls: assert property (
        @(posedge CLK) (!SET && !SLEEP_B && (D == 1'b1)) |=> (Q == 1'b1)
    );

    // With no controls and D=0, Q becomes 0 next cycle.
    check_d0_captured_when_no_controls: assert property (
        @(posedge CLK) (!SET && !SLEEP_B && (D == 1'b0)) |=> (Q == 1'b0)
    );

endmodule

verilog_code:
module clk_divider( sysclk, slowclk );
   input 	sysclk; 	output 	slowclk;	reg [6:0] 	counter; reg		slowclock;

   initial begin
      counter = 0;
      slowclock = 1;
   end

   always @ (posedge sysclk) begin
		if(counter == 'D50) begin
			counter <= 0;
			slowclock <= ~slowclock;
		end else begin
			counter <= counter + 1;
		end
   end

   assign slowclk = slowclock;

endmodule

sva_code:
module clk_divider_sva (
    input logic sysclk,
    input logic slowclk
);
    // Clock: sysclk; Reset: none; Sequential divider toggling slowclk every 51 sysclk cycles (period 102).

    // After any slowclk edge, it must be stable for the next 50 cycles.
    slowclk_no_early_toggle_50: assert property (
        @(posedge sysclk) $changed(slowclk) |-> (!$changed(slowclk))[*50]
    );

    // After any slowclk edge, it must toggle again exactly 51 cycles later.
    slowclk_toggle_at_51: assert property (
        @(posedge sysclk) $changed(slowclk) |-> ##51 $changed(slowclk)
    );

    // A rising edge is followed by a falling edge 51 cycles later (no earlier changes).
    slowclk_rise_then_fall_51: assert property (
        @(posedge sysclk) $rose(slowclk) |-> (!$changed(slowclk))[*50] ##1 $fell(slowclk)
    );

    // A falling edge is followed by a rising edge 51 cycles later (no earlier changes).
    slowclk_fall_then_rise_51: assert property (
        @(posedge sysclk) $fell(slowclk) |-> (!$changed(slowclk))[*50] ##1 $rose(slowclk)
    );

    // Rising edge repeats every 102 cycles (full period).
    slowclk_rise_period_102: assert property (
        @(posedge sysclk) $rose(slowclk) |-> ##102 $rose(slowclk)
    );

    // Falling edge repeats every 102 cycles (full period).
    slowclk_fall_period_102: assert property (
        @(posedge sysclk) $fell(slowclk) |-> ##102 $fell(slowclk)
    );

    // No back-to-back toggles on consecutive sysclk cycles.
    slowclk_no_adjacent_toggles: assert property (
        @(posedge sysclk) $changed(slowclk) |-> ##1 !$changed(slowclk)
    );

endmodule

verilog_code:
module add_4bit(
    input [3:0] A,
    input [3:0] B,
    output [4:0] C
);

    wire [3:0] S;
    wire C0, C1, C2;

    // First full adder
    full_adder fa1 (
        .a(A[0]),
        .b(B[0]),
        .c_in(1'b0),
        .s(S[0]),
        .c_out(C0)
    );

    // Second full adder
    full_adder fa2 (
        .a(A[1]),
        .b(B[1]),
        .c_in(C0),
        .s(S[1]),
        .c_out(C1)
    );

    // Third full adder
    full_adder fa3 (
        .a(A[2]),
        .b(B[2]),
        .c_in(C1),
        .s(S[2]),
        .c_out(C2)
    );

    // Fourth full adder
    full_adder fa4 (
        .a(A[3]),
        .b(B[3]),
        .c_in(C2),
        .s(S[3]),
        .c_out(C[4])
    );

    assign C[3:0] = S;
    assign C[4] = C[4];

endmodule

module full_adder(
    input a,
    input b,
    input c_in,
    output s,
    output c_out
);

    assign s = a ^ b ^ c_in;
    assign c_out = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva_code:
module add_4bit_sva (
    input logic CLK,           // External verification clock (DUT has no clock)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] C
);
    // Helper expressions for ripple-carry expansion based only on A and B
    let carry0 = (A[0] & B[0]);
    let carry1 = (A[1] & B[1]) | ((A[1] ^ B[1]) & carry0);
    let carry2 = (A[2] & B[2]) | ((A[2] ^ B[2]) & carry1);
    let carry3 = (A[3] & B[3]) | ((A[3] ^ B[3]) & carry2);

    ///// Functional correctness /////
    // Sum equals A+B.
    check_sum_correct: assert property (
        @(posedge CLK) C == (A + B)
    );
    // LSB is XOR of A[0] and B[0] (c_in = 0).
    check_bit0_xor: assert property (
        @(posedge CLK) C[0] == (A[0] ^ B[0])
    );
    // Bit1 equals XOR of A[1], B[1], and carry0.
    check_bit1_sum: assert property (
        @(posedge CLK) C[1] == (A[1] ^ B[1] ^ carry0)
    );
    // Bit2 equals XOR of A[2], B[2], and carry1.
    check_bit2_sum: assert property (
        @(posedge CLK) C[2] == (A[2] ^ B[2] ^ carry1)
    );
    // Bit3 equals XOR of A[3], B[3], and carry2.
    check_bit3_sum: assert property (
        @(posedge CLK) C[3] == (A[3] ^ B[3] ^ carry2)
    );
    // Carry-out equals carry3.
    check_carry_out: assert property (
        @(posedge CLK) C[4] == carry3
    );

    ///// Identities and range /////
    // Adding zero on A passes B through.
    check_zero_identity_A: assert property (
        @(posedge CLK) (A == 4'd0) |-> (C == B)
    );
    // Adding zero on B passes A through.
    check_zero_identity_B: assert property (
        @(posedge CLK) (B == 4'd0) |-> (C == A)
