module alu_sva (
    input logic CLK,
    input logic RESETn,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [4:0]  aluc,
    input logic [31:0] result
);
    // Addition (signed) opcode 0: result = a + b
    check_add_signed: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd0) |-> (result == (a + b))
    );

    // Addition (unsigned) opcode 1: result = a + b
    check_add_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd1) |-> (result == (a + b))
    );

    // Subtraction (signed) opcode 2: result = a - b
    check_sub_signed: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd2) |-> (result == (a - b))
    );

    // Subtraction (unsigned) opcode 3: result = a - b
    check_sub_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd3) |-> (result == (a - b))
    );

    // Bitwise AND opcode 4: result = a & b
    check_and: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd4) |-> (result == (a & b))
    );

    // Bitwise OR opcode 5: result = a | b
    check_or: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd5) |-> (result == (a | b))
    );

    // Bitwise XOR opcode 6: result = a ^ b
    check_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd6) |-> (result == (a ^ b))
    );

    // Bitwise NOR opcode 7: result = ~(a | b)
    check_nor: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd7) |-> (result == ~(a | b))
    );

    // Set Less Than (signed) opcode 8: result = 1 or 0 per signed comparison
    check_slt_signed: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (aluc == 5'd8) |-> (result == ((a[31]^b[31]) ? (a[31] ? 32'd1 : 32'd0) : ((a < b) ? 32'd1 : 32'd0)))
    );

    // Set Less Than (unsigned) opcode 9: result = 1 or 0 per unsigned comparison
    check_slt_unsigned: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (aluc == 5'd9) |-> (result == ((a < b) ? 32'd1 : 32'd0))
    );

    // Shift Left Logical opcode 10: result = b << a
    check_sll: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd10) |-> (result == (b << a))
    );

    // Shift Right Logical opcode 11: result = b >> a
    check_srl: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11) |-> (result == (b >> a))
    );

    // Shift Right Arithmetic opcode 12: result = $signed(b) >>> a
    check_sra: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12) |-> (result == ($signed(b) >>> a))
    );

    // Load Upper Immediate opcode 14: result = {b[15:0], 16'b0}
    check_lui: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd14) |-> (result == {b[15:0], 16'b0})
    );

    // Zero opcode 31: result = 0
    check_zero_opcode: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd31) |-> (result == 32'd0)
    );

    // Default/invalid opcode: result = 0
    check_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!(aluc inside {5'd0,5'd1,5'd2,5'd3,5'd4,5'd5,5'd6,5'd7,5'd8,5'd9,5'd10,5'd11,5'd12,5'd14,5'd31})) |-> (result == 32'd0)
    );

    // Shift-by-zero identity for SLL: a==0 leaves b unchanged
    check_sll_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd10 && a == 32'd0) |-> (result == b)
    );

    // Shift-by-zero identity for SRL: a==0 leaves b unchanged
    check_srl_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11 && a == 32'd0) |-> (result == b)
    );

    // Shift-by-zero identity for SRA: a==0 leaves b unchanged
    check_sra_shift0_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12 && a == 32'd0) |-> (result == b)
    );

    // SRL with nonzero shift inserts 0 at MSB
    check_srl_msb_zero_on_shift: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd11 && a != 32'd0) |-> (result[31] == 1'b0)
    );

    // SRA with nonzero shift preserves sign bit at MSB
    check_sra_msb_sign_extend: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd12 && a != 32'd0) |-> (result[31] == b[31])
    );

    // LUI guarantees lower 16 bits are zero
    check_lui_low16_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc == 5'd14) |-> (result[15:0] == 16'b0)
    );
endmodule

verilog_code:
module adder4bit(
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] temp_sum;
  wire [3:0] temp_carry;

  // Full adder for the least significant bit
  full_adder fa0(
    .a(a[0]),
    .b(b[0]),
    .cin(cin),
    .sum(temp_sum[0]),
    .cout(temp_carry[0])
  );

  // Full adder for the second least significant bit
  full_adder fa1(
    .a(a[1]),
    .b(b[1]),
    .cin(temp_carry[0]),
    .sum(temp_sum[1]),
    .cout(temp_carry[1])
  );

  // Full adder for the third least significant bit
  full_adder fa2(
    .a(a[2]),
    .b(b[2]),
    .cin(temp_carry[1]),
    .sum(temp_sum[2]),
    .cout(temp_carry[2])
  );

  // Full adder for the most significant bit
  full_adder fa3(
    .a(a[3]),
    .b(b[3]),
    .cin(temp_carry[2]),
    .sum(temp_sum[3]),
    .cout(cout)
  );

  assign sum = temp_sum;

endmodule
module full_adder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva_code:
module adder4bit_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // Local derived ripple carries from inputs
    logic c0, c1, c2;
    assign c0 = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
    assign c1 = (a[1] & b[1]) | (a[1] & c0) | (b[1] & c0);
    assign c2 = (a[2] & b[2]) | (a[2] & c1) | (b[2] & c1);

    ///// Functional correctness /////
    // 5-bit result equals a + b + cin.
    check_add_result: assert property (
        @(posedge CLK) disable iff (1'b0) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );
    // sum[0] is XOR of a[0], b[0], cin.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[0] == (a[0] ^ b[0] ^ cin)
    );
    // sum[1] is XOR of a[1], b[1], and carry from bit 0.
    check_sum1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[1] == (a[1] ^ b[1] ^ c0)
    );
    // sum[2] is XOR of a[2], b[2], and carry from bit 1.
    check_sum2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[2] == (a[2] ^ b[2] ^ c1)
    );
    // sum[3] is XOR of a[3], b[3], and carry from bit 2.
    check_sum3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[3] == (a[3] ^ b[3] ^ c2)
    );
    // cout is majority of a[3], b[3], and carry from bit 2.
    check_cout_majority: assert property (
        @(posedge CLK) disable iff (1'b0) cout == ((a[3] & b[3]) | (a[3] & c2) | (b[3] & c2))
    );
endmodule

module counter_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic [31:0] count
);
    // Clock: clk (posedge). Reset: rst (active-high, synchronous).
    // Sequential logic: posedge clocked counter with enable.
    // Behavior: rst -> count=0; else if enable -> count=count+1; else hold.

    // When rst is high at the clock edge, count is driven to 0.
    reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 32'd0)
    );

    // Outside reset, next-state equals previous plus (enable ? 1 : 0).
    next_state_function: assert property (
        @(posedge clk) disable iff (rst) (!$initstate) |-> (count == $past(count) + (enable ? 32'd1 : 32'd0))
    );

    // Outside reset, if count changes, enable must be 1.
    change_implies_enable: assert property (
        @(posedge clk) disable iff (rst) (!$initstate && (count != $past(count))) |-> enable
    );

    // Outside reset, if enable is 1, count must change.
    enable_implies_change: assert property (
        @(posedge clk) disable iff (rst) (!$initstate && enable) |-> (count != $past(count))
    );

    // While rst is held high across cycles, count stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) (!$initstate && rst && $past(rst)) |-> (count == 32'd0) && ($past(count) == 32'd0)
    );

    // On the first cycle after reset deasserts with enable=0, count remains 0.
    post_reset_zero_if_disabled: assert property (
        @(posedge clk) (!$initstate && $past(rst) && !rst && !enable) |-> (count == 32'd0)
    );

    // On the first cycle after reset deasserts with enable=1, count becomes 1.
    post_reset_one_if_enabled: assert property (
        @(posedge clk) (!$initstate && $past(rst) && !rst && enable) |-> (count == 32'd1)
    );
endmodule

verilog_code:
module binary_counter (
  input clk,
  input reset,
  output reg [2:0] count,
  output reg enable
);

  always @(posedge clk) begin
    if (reset) begin
      count <= 3'b000;
      enable <= 1'b0;
    end
    else begin
      if (count == 3'b101) begin
        count <= 3'b000;
        enable <= 1'b1;
      end
      else begin
        count <= count + 1;
        enable <= 1'b0;
      end
    end
  end

endmodule

sva_code:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [2:0] count,
  input logic enable
);

  // On reset, next cycle drives count=0 and enable=0.
  reset_next_outputs_zero: assert property (
    @(posedge clk) reset |=> (count == 3'b000) && (enable == 1'b0)
  );

  // From count=0, next is 1 and enable=0.
  next_from_0: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b000) |=> (count == 3'b001) && (enable == 1'b0)
  );

  // From count=1, next is 2 and enable=0.
  next_from_1: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b001) |=> (count == 3'b010) && (enable == 1'b0)
  );

  // From count=2, next is 3 and enable=0.
  next_from_2: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b010) |=> (count == 3'b011) && (enable == 1'b0)
  );

  // From count=3, next is 4 and enable=0.
  next_from_3: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b011) |=> (count == 3'b100) && (enable == 1'b0)
  );

  // From count=4, next is 5 and enable=0.
  next_from_4: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b100) |=> (count == 3'b101) && (enable == 1'b0)
  );

  // From count=5, next is 0 and enable=1.
  next_from_5: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b101) |=> (count == 3'b000) && (enable == 1'b1)
  );

  // From count=6, next is 7 and enable=0.
  next_from_6: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b110) |=> (count == 3'b111) && (enable == 1'b0)
  );

  // From count=7, next is 0 and enable=0.
  next_from_7: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b111) |=> (count == 3'b000) && (enable == 1'b0)
  );

  // Enable is a single-cycle pulse.
  enable_one_cycle_pulse: assert property (
    @(posedge clk) disable iff (reset) (enable == 1'b1) |=> (enable == 1'b0)
  );

  // When enable is 1, the count in that cycle is 0.
  enable_implies_count_zero: assert property (
    @(posedge clk) disable iff (reset) (enable == 1'b1) |-> (count == 3'b000)
  );

  // While count is 5, enable is 0 in that same cycle.
  count5_implies_enable_zero: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b101) |-> (enable == 1'b0)
  );

endmodule

verilog_code:
module calculator(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] result
);

always @*
begin
    case(op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: result = a / b;
    endcase
end

endmodule

sva_code:
module calculator_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

    // 8-bit add (wraps to 8 bits)
    function automatic [7:0] add8 (input [7:0] x, input [7:0] y);
        add8 = x + y;
    endfunction
    // 8-bit sub (wraps to 8 bits)
    function automatic [7:0] sub8 (input [7:0] x, input [7:0] y);
        sub8 = x - y;
    endfunction
    // 8-bit mul (low 8 bits of product)
    function automatic [7:0] mul8 (input [7:0] x, input [7:0] y);
        mul8 = x * y;
    endfunction
    // 8-bit div (truncated integer divide)
    function automatic [7:0] div8 (input [7:0] x, input [7:0] y);
        div8 = x / y;
    endfunction

    ///// Functional correctness for each op /////
    // When op==00, result is 8-bit a+b (wrap).
    check_add_correct: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == add8(a, b))
    );
    // When op==01, result is 8-bit a-b (wrap).
    check_sub_correct: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == sub8(a, b))
    );
    // When op==10, result is low 8 bits of a*b.
    check_mul_correct: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == mul8(a, b))
    );
    // When op==11, result is a/b (8-bit integer divide).
    check_div_correct: assert property (
        @(posedge clk) (op == 2'b11) |-> (result == div8(a, b))
    );

    ///// Combinational purity /////
    // If a, b, op are stable, result must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({a, b, op}) |-> $stable(result)
    );

    ///// Simple algebraic identities per operation /////
    // Add: +0 is identity.
    check_add_identity_b0: assert property (
        @(posedge clk) (op == 2'b00) && (b == 8'h00) |-> (result == a)
    );
    // Add: 0+ is identity.
    check_add_identity_a0: assert property (
        @(posedge clk) (op == 2'b00) && (a == 8'h00) |-> (result == b)
    );
    // Sub: -0 is identity.
    check_sub_identity_b0: assert property (
        @(posedge clk) (op == 2'b01) && (b == 8'h00) |-> (result == a)
    );
    // Sub: x-x = 0 (8-bit wrap).
    check_sub_self_zero: assert property (
        @(posedge clk) (op == 2'b01) && (a == b) |-> (result == 8'h00)
    );
    // Mul: 0 is annihilator.
    check_mul_zero: assert property (
        @(posedge clk) (op == 2'b10) && ((a == 8'h00) || (b == 8'h00)) |-> (result == 8'h00)
    );
    // Mul: 1 is identity (a*1 = a).
    check_mul_identity_b1: assert property (
        @(posedge clk) (op == 2'b10) && (b == 8'h01) |-> (result == a)
    );
    // Mul: 1 is identity (1*b = b).
    check_mul_identity_a1: assert property (
        @(posedge clk) (op == 2'b10) && (a == 8'h01) |-> (result == b)
    );
    // Div: /1 is identity.
    check_div_by_one: assert property (
        @(posedge clk) (op == 2'b11) && (b == 8'h01) |-> (result == a)
    );
    // Div: 0/x = 0 for nonzero x.
    check_div_zero_numer: assert property (
        @(posedge clk) (op == 2'b11) && (a == 8'h00) && (b != 8'h00) |-> (result == 8'h00)
    );
    // Div: x/x = 1 for nonzero x.
    check_div_self_one: assert property (
        @(posedge clk) (op == 2'b11) && (a == b) && (b != 8'h00) |-> (result == 8'h01)
    );

endmodule

module data_comp_decomp_sva (
    input logic CLK,          // sampling clock for SVA (DUT is combinational)
    input logic [7:0] data_in,
    input logic [3:0] data_out,
    input logic       valid
);
    // Analysis: no clock/reset in DUT; purely combinational; maps 4 encodings, else invalid.

    // data_in == 8'h01 maps to data_out == 4'h1 with valid == 1
    check_map_sym1: assert property (
        @(posedge CLK) (data_in == 8'h01) |-> ((data_out == 4'h1) && (valid == 1'b1))
    );

    // data_in == 8'h02 maps to data_out == 4'h2 with valid == 1
    check_map_sym2: assert property (
        @(posedge CLK) (data_in == 8'h02) |-> ((data_out == 4'h2) && (valid == 1'b1))
    );

    // data_in == 8'h04 maps to data_out == 4'h3 with valid == 1
    check_map_sym3: assert property (
        @(posedge CLK) (data_in == 8'h04) |-> ((data_out == 4'h3) && (valid == 1'b1))
    );

    // data_in == 8'h08 maps to data_out == 4'h4 with valid == 1
    check_map_sym4: assert property (
        @(posedge CLK) (data_in == 8'h08) |-> ((data_out == 4'h4) && (valid == 1'b1))
    );

    // For all other data_in values, data_out == 0 and valid == 0
    check_default_map: assert property (
        @(posedge CLK) !(data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> ((data_out == 4'h0) && (valid == 1'b0))
    );

    // valid == 1 occurs only for recognized inputs
    check_valid_high_implies_recognized: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_in inside {8'h01,8'h02,8'h04,8'h08})
    );

    // Recognized inputs always produce valid == 1
    check_recognized_implies_valid_high: assert property (
        @(posedge CLK) (data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> (valid == 1'b1)
    );

    // valid == 0 implies data_out == 0
    check_valid_low_implies_zero: assert property (
        @(posedge CLK) (valid == 1'b0) |-> (data_out == 4'h0)
    );

    // data_out == 0 implies valid == 0
    check_zero_implies_valid_low: assert property (
        @(posedge CLK) (data_out == 4'h0) |-> (valid == 1'b0)
    );

    // Non-zero data_out implies recognized input and valid == 1
    check_nonzero_out_implies_recognized_and_valid: assert property (
        @(posedge CLK) (data_out != 4'h0) |-> ((data_in inside {8'h01,8'h02,8'h04,8'h08}) && (valid == 1'b1))
    );

    // valid == 1 implies data_out is one of 4'h1..4'h4
    check_valid_high_implies_known_code: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_out inside {4'h1,4'h2,4'h3,4'h4})
    );
endmodule

